quests[28590] = { id = 28590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung", description = "Dieser Allianzabschaum wird endlich kriegen, was er verdient. Außerdem gibt es da etwas, das uns gehört. Ich habe einen Frontalangriff auf Hochstade autorisiert.\n\nGeht an Bord der Himmelsreißer und stürzt Euch in den Kampf. Flick wird Euch alles erklären, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Flick auf der Himmelsreißer, die über Hochstade kreist.", completion = "Gut, dass Ihr hier seid, {name}. Seid Ihr bereit, ein wenig Chaos zu verbreiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[28591] = { id = 28591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Mauer, auf der Lauer", description = "Ihr seht aus, als hättet Ihr Lust auf einen Kampf. Setzt Euch in einen der Geschütztürme und macht die Verteidiger auf der Mauer fertig.\n\nUnd zwar schnell. Am besten, bevor wir als großer Feuerball enden.", sourceObjective = "Vernichtet 80 Scharfschützen von Hochstade, 12 Kanoniere von Hochstade und 4 Kanonen von Hochstade mit dem Geschützturm des Himmelsreißers.", completion = "Die modernisierte goblinische Zerstörungskraft ist erstaunlich, oder? Ich liebe diese Dinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[28592] = { id = 28592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschiedspakete", description = "Flick verfolgt sicherlich einen größeren Plan, aber das wäre kein Angriff, wenn wir nicht wenigstens ein paar explosive Geschenke zurücklassen würden.\n\nGeht runter und bringt etwas von dem Sprengstoff auf dem Boot, am Festungseingang und in einem der nördlichen Türme an. Damit sollten sie eine Weile beschäftigt sein.\n\nWir werden uns ebenfalls zum Boden begeben. Trefft uns am östlichen Turm, wenn Ihr fertig seid.", sourceObjective = "Legt Bomben auf dem Boot, am Festungseingang und in einem der nördlichen Türme.", completion = "Hahah! Tolle Vorstellung.\n\nDamit haben wir sie ordentlich im Hochland willkommen geheißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28593] = { id = 28593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von größter Wichtigkeit", description = "Mit Garroshs Zeppelin ist auch das Induktionssamophlang, das Ihr für uns in Azshara geborgen habt, abgestürzt. Die Allianz hat es irgendwo in dieser Festung versteckt. Krazz will es wiederhaben.\n\nIch tippe auf den Keller der Festung, also beginnt Eure Suche dort. Kehrt zu mir in die Nähe des Ostturms zurück, wenn Ihr es in Händen haltet.", sourceObjective = "Beschafft das Induktionssamophlang.", progress = "Krazz wartet. Trödelt nicht.", completion = "Brillant! Dafür wird Krazz Euch auf Händen tragen. Freut mich für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28594] = { id = 28594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichtmehrganzsohochstade", description = "Geht runter und scheucht dieses Allianzgesindel auf. Egal, welches. Sie sollen wie kopflose Hühner umherlaufen, damit Ihr Euch auf das echte Ziel konzentrieren könnt.\n\nIhr findet uns nahe des Ostturms, wenn Ihr fertig seid.", sourceObjective = "Tötet 10 Verteidiger von Hochstade.", completion = "So macht man das. Kopflose Hühner... Aber eine große Klappe hatten sie schon, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28595] = { id = 28595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazz werkelt!", description = "Das war's. Wir sind fertig. Lasst uns aufbrechen.\n\nMolch hat ein paar Gyrokopter an der Spitze des Turms angebunden. Geht zu ihr und fliegt kurz zurück zu den Krazzwerken. Wir räumen hier auf.", sourceObjective = "Sprecht mit Molch, um zu den Krazzwerken zurückzufliegen. Gebt dort Kapitän Krazz das Induktionssamophlang.", progress = "Sagt mir, dass Ihr es geschafft habt. Ihr schafft es immer. Zeigt mir meine Schönheit!", completion = "Darauf habe ich mich die ganze Zeit gefreut! Mit dieser Schönheit hebt die Flotte schon bald wieder ab.\n\nIhr wisst genau, was ich mag, {name}. Und ich weiß, was Ihr mögt - nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[28596] = { id = 28596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Hochstade!", description = "Willkommen im Hochland, <Soldat/Soldatin>. Ihr kommt gerade rechtzeitig.\n\nDie Hordentruppen haben gerade mit ihrem Luftangriff begonnen. Unternehmt etwas dagegen. Werdet sie los!", sourceObjective = "Tötet 10 Angreifer der Horde in Hochstade.", completion = "Das sieht schon besser aus. Den Rest kehren wir von hier aus der Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28597] = { id = 28597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenfutter", description = "Har! Wir können direkt loslegen, {name}. Hochstade hat anscheinend ein echt großes Zeppelinproblem. Das Luftschiff zerlegt die Mauern.\n\nIch habe eine Idee, die so dämlich ist, dass man sie genial nennen könnte. Ich brauche nur etwas Kanonenpulver.\n\nSammelt alles Pulver ein, das ihr in Hochstade finden könnt und trefft mich im Handelsviertel!", sourceObjective = "Sammelt 10 Säcke mit Kanonenpulver.", progress = "Ich brauche mehr Pulver! Bringt mir mehr Pulver! Mehr mehr mehr!", completion = "Jawoll, das reicht.\n\n<Flintlocke stopft sich etwas von dem Pulver in den Mund.>\n\nOhhh, frisch. Berauschend. Feinstes Korn aus dem Rotkammgebirge mit einem Hauch Westfallschwefel und einem milden Nachgeschmack. Hochstade kriegt nur das Beste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28598] = { id = 28598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hohes Ziel", description = "Seht mal, {name}. Ich hab' die größte Waffe in Hochstade! Wir werden 'ne Taktik ausprobieren, die mein Papa von seinem Papa und der von seinem Papa, kurz bevor er in die Luft flog, gelernt hat.\n\nSie nennt sich \"{class}-Schuss.\"\n\nMan nimmt <einen/eine> {race} {class}, steckt <ihn/sie> in 'ne riesige Kanone und dann - hey, entspannt Euch. Das haut meistens hin.\n\nNehmt den Sprengstoff und wartet neben mir. Wenn das Luftschiffchen wieder vorbeikommt, schieße ich Euch aufs Deck. Bringt den Sprengstoff in seinem Rumpf an und... keine Ahnung, denkt Euch was aus.", sourceObjective = "Wartet, bis Euch Fargo Flintlocke auf den Zeppelin gebracht hat und bringt seine Sprengladung in der unteren Kabine an.", progress = "Es gibt kein Problem, das man nicht mit einer Bombe lösen könnte.", completion = "<Flintlocke wischt sich die Tränen aus den Augen.>\n\nOh, {name}. {name}!\n\nDas ... war wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[28599] = { id = 28599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurdran wartet", description = "Der Angriff hat anscheinend aufgehört, {name}. Eigentlich schade, sonst hätten wir die {class}-Rakete noch ausprobieren können.\n\nWie dem auch sei, Kurdran Wildhammer steht oben auf der Festung. Er will Euch garantiert als <Helden/Heldin> feiern. Habt Ihr auch verdient! Redet mal mit ihm!\n\nIch gehe schon mal vor und erkunde den Strand.", sourceObjective = "Sprecht mit Kurdran Wildhammer in der Burg Hochstade im Schattenhochland.", completion = "Ihr wurdet vom König persönlich geschickt? Es freut mich, dass Sturmwind sicher ist.\n\nIch hatte eigentlich weitere Truppen erwartet, aber so wie man hört, wurde die Allianzflotte auf dem Weg hierher von der Horde angegriffen. Sie haben alles gegeben, trotzdem wurde ihre Flotte zerschossen.\n\nWenn wir hier im Hochland Fortschritte machen wollen, werden wir die Hilfe von Helden wie Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28600] = { id = 28600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Loyalität", description = "Ich habe keine Entscheidungsgewalt bei solchen Angelegenheiten. Ihr müsst mit unserem Anführer Drek'Thar sprechen. Ich habe Eure Ankunft in Burg Frostwolf bereits angekündigt. Drek'Thar wird sich persönlich mit Euch treffen.", sourceObjective = "Sprecht mit Drek'Thar.", completion = "<Oberster Kriegsfürst Cromush wird blass.>\n\nSIE LASSEN UNS IM STICH? SIE LASSEN DIE HORDE IM STICH? Das kann nicht sein!\n\nIch...\n\n<Cromush geht auf ein Knie.>\n\nIch... ICH WERDE NICHT AUFGEBEN. Wir werden das auch ohne ihre Hilfe schaffen. Zur Hölle mit den Frostwölfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28601] = { id = 28601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alter Kahn" }
quests[28602] = { id = 28602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid vorbereitet", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt, ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nNun, meine Seile waren in dem Wagen voller Sprengstoff, den Ihr in die Luft gejagt habt.\n\nWieso seht Ihr Euch nicht mal hier um, ob Ihr noch etwas findet.", sourceObjective = "Sammelt 6 Stücke Seil.", progress = "Was macht die Suche?", completion = "Irgendwie habe ich das Gefühl, ich werde es brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28603] = { id = 28603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration", description = "Hier ist Eure nächste Mission: Reist nach Westen zur Landzunge und infiltriert das Übungsgelände der Sturmlanzen. Dort gibt es zwar hunderte Sturmlanzen in der Ausbildung, aber eine meiner Banshees wird Euch so tarnen, dass Ihr wie einer der Menschen ausseht, die vor kurzem gefangen genommen wurden. Dann könnt Ihr Euch frei zwischen den Feinden bewegen.\n\nBetretet die Landzunge und sucht nach den Ausbildern der Sturmlanzen. Findet sie und bringt sie dazu, Euch anzugreifen! Wenn sie das tun, bringt Ihr sie um. Ohne ihre Ausbilder werden sie keine weiteren Soldaten mehr unterweisen können!", sourceObjective = "Tötet Ausbilder Rufus, Ausbildungsoffizier Magnus und Hauptmann Rattenbart.", sourceObjectiveStatus = "unverified-source-field" }
quests[28604] = { id = 28604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuschung und Betrug", description = "Solange ich an Eurer Seite bleibe, werden die Feinde Euch für <einen/eine> der ihren halten. Eure neue Menschlichkeit sollte Euch allerdings nicht dazu verleiten, draufgängerisch zu werden. Wenn Ihr Aufmerksamkeit erregt, werden die Zwerge misstrauisch und Euch wahrscheinlich angreifen!\n\nDoch ich habe einen Plan. Nehmt dieses Fass mit vergiftetem Wasser und stillt damit den Durst von müden Lehrlingen der Sturmlanzen. Wenn sie davon trinken, werden sie todkrank und schließlich an dem Gift sterben.", sourceObjective = "Vergiftet 30 Lehrlinge der Sturmlanzen mit dem Wasserfass.", progress = "Täuschung und Betrug - dies sind Eure Werkzeuge!", completion = "Sie werden nicht sofort sterben, aber sterben WERDEN sie! Wenn sie erkennen, wer für den Tod ihrer Soldaten verantwortlich ist, werdet Ihr längst weg sein - ein Phantom des Todes!", sourceObjectiveStatus = "unverified-source-field" }
quests[28605] = { id = 28605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung", description = "<Melisaras Gedanken mischen sich in Eure eigenen.>\n\nEure letzte Aufgabe wird ein Angriff auf die Belagerungstechniker von Gavins Landspitze, westlich der Landzunge, sein. Brecht zum letzten Finger auf und vernichtet die Zwergen- und Gnomeningenieure, die für den Bau und die Befestigung der Kriegsmaschinen der Sturmlanzen verantwortlich sind. Vergesst nicht, Cromushs letzte Hosentaschenbombe zu platzieren.", sourceObjective = "Tötet 10 Ingenieure der Sturmlanzen.", completion = "Die Streitkräfte der Sturmlanzen sind geschwächt. Es ist Zeit für die Sprengung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28606] = { id = 28606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel für den Hot Rod" }
quests[28607] = { id = 28607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel für den Hot Rod" }
quests[28608] = { id = 28608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengrab", description = "Es freut mich, dass Ihr wieder auf den Beinen seid, {name}. Ihr habt Euch gut gehalten, obwohl Ihr so lange tot wart!\n\nAndere hatten weniger Glück. Würdet Ihr meine Balsamierungsflüssigkeit und etwas Faden holen, damit ich diese Leichen zusammenflicken kann? Beides werdet Ihr im Schattengrab, dem Gebäude direkt hinter mir, finden.\n\nDarnell wird Euch begleiten. Er kennt den Weg.", sourceObjective = "Holt zähe Balsamierungsflüssigkeit und Leichenflickerzwirn aus dem Schattengrab in Todesend.", progress = "Ihr findet die Gegenstände im Schattengrab. Ich glaube, ich habe sie auf meinem Arbeitstisch liegen gelassen.", completion = "Genau die brauche ich. Ihr werdet für die Verlassenen von Nutzen sein, {name}.\n\nMan sagt, dass Ihr in Eurem letzten Leben ein ziemlich guter {class} wart. Vielleicht sollte ich Euch eine etwas aufregendere Aufgabe geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28609] = { id = 28609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerschläge", description = "Seit Wochen streiten wir drei uns darüber, wessen Waffen die besten sind.\n\nNiemand soll behaupten, dass meine Streitkolben zweitklassig wären. Kilrams Äxte und Serils Schwerter kommen niemals an die Stärke meiner Waffe heran.\n\nDer Streit geht mir auf die Nerven. Ich werde den beiden mit einer kleinen Vorführung beweisen, dass ich recht habe. Würdet Ihr bitte nach draußen gehen und Deez Felsklau sagen, dass ich den größten Felsbrocken brauche, den er auftreiben kann?", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Lilith möchte also, dass ich einen Felsbrocken in das Observatorium bringe? Das ist mein Geschäft: kompakte Waren. Normalerweise kommen Einzelkunden nicht zu mir, aber ich werde bestimmt keine Fragen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28610] = { id = 28610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grollendes Geröll", description = "Ihr könnt den Felsbrocken mit meinem patentierten Fels-in-der-Kiste hineinbringen! Normalerweise würde ich ihn Euch einfach verkaufen, aber mir sind die Materialien ausgegangen.\n\nAuf dem Gipfel südlich der Stadt sind Erdelementare aufgetaucht. Die sind eine gute Quelle für Geröll. Bringt mir genug davon, dann bezahle ich Euch für die Aufstockung meines Lagers und lege noch einen Fels-in-der-Kiste dazu. Umsonst!", sourceObjective = "Beschafft 6 hochwertige Geröllbrocken von Frostsplitterrumplern.", progress = "Habt Ihr das Geröll?", completion = "Das sollte reichen! Hier ist Eure Bezahlung, wie versprochen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28611] = { id = 28611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual der Entweiher", description = "Ah, ich sehe bereits klarer, {name}.\n\nEs ist richtig, den bösartigen Neferset zu misstrauen. Ich spüre bereits, dass sie hinter den Kräften stecken, die den Fluss verderben.\n\nTaucht noch einmal hinab und findet die Finstergrundhöhle. Ihr werdet sehen, dass die Neferset dort ein dunkles Ritual der Verderbnis ausüben.\n\nHaltet sie auf, damit der Fluss wieder rein wird.", sourceObjective = "Unterbrecht das Ritual der Neferset in der Finstergrundhöhle.", completion = "Das Wasser des Flusses ist fast wieder klar. Unsere prophetischen Visionen werden bald zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28612] = { id = 28612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrison Jones und der Tempel von Uldum", description = "Wir haben viel durchgemacht, aber das scheint sich jetzt endlich auszuzahlen!\n\nUns trennen nur noch wenige Schritte von der Lade... Ich habe die Chiffren studiert, um sie zu enthüllen... Schnottz hält uns für tot.\n\nIch glaube, wir kriegen das doch noch hin!", sourceObjective = "Erbeutet die Lade der Verheißung.", completion = "Aber Ihr habt Glück, denn dieser Zwerg hat noch ein oder zwei Asse im Ärmel!\n\nHeehee! ...Ihr hättet Euren Gesichtsausdruck sehen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28613] = { id = 28613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sehen uns auf der anderen Seite!", description = "Also gut, {name}. Wir haben uns ein wenig Zeit verschafft, aber die dürfen wir nicht vertrödeln.\n\nFolgt mir!", sourceObjective = "Sprecht mit Harrison Jones auf dem Aufstieg des Schöpfers in Uldum.", completion = "So weit, so gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[28614] = { id = 28614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärserker", description = "Die Abwesenheit von Oberhäuptling Winterfell hat den Zorn der Winterfelle nicht gerade gemindert. In der Zwischenzeit hat ihr größter Krieger enorme Macht an sich gerissen.\n\nGrolnar der Berserker haust in der Höhle ganz oben im Lager der Winterfelle. In ihm steckt genug verderbtes Feuerwasser, um zehn normale Furbolgs zu töten.\n\nEr ist zu einer aufgeblähten, schrecklichen Bestie geworden! Unsere Krieger werden mit ihm nicht fertig... seid Ihr stark genug, um ihn zu besiegen, {class}?", sourceObjective = "Tötet Grolnar den Berserker.", completion = "Eure Taten beweisen mir und der Holzschlundfeste wieder einmal, was für ein mächtiger Krieger Ihr seid!\n\nHoffentlich haben wir die Winterfelle damit endgültig besiegt...", sourceObjectiveStatus = "unverified-source-field" }
quests[28615] = { id = 28615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdwiderstand", description = "Trotz ihres Wahnsinns und ihrer Verderbnis klammern sich die Winterfelle mit letzter Kraft an ihre schamanischen Kräfte. Dass sie die Macht der Elemente benutzen, um meinem Stamm und anderen Unschuldigen Schaden zuzufügen, verstört mich.\n\nWir werden ihre Totems gegen sie wenden! Nehmt mein Totem mit ins Lager der Winterfelle. Setzt seine Macht aus der Ferne bei den Totems der Winterfelle ein, dann wird der Zorn der Erde über alle kommen, die sich in der Nähe aufhalten!\n\nDass Ihr einen Sicherheitsabstand einhalten solltet, muss ich wohl nicht erwähnen!", sourceObjective = "Überladet 4 Erdtotems der Winterfelle mit Tanrirs überladenem Totem.", completion = "Mögen die Winterfelle nie wieder die Holzschlundfeste bedrohen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28616] = { id = 28616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzenapokalypse", description = "Bevor wir fortfahren, möchte ich um eine Schweigeminute für unseren gefallenen Bruder Orkus bitten, ohne den wir von den Sturmlanzen vernichtet worden wären. Das ist für Euch, Bruder!\n\n<Cromush geht auf ein Knie.>\n\nNun, {name}, glaubt nicht, dass ich Euren Anteil an all dem vergessen hätte! Deshalb gewähre ich Euch die Ehre, die goblinischen Hosentaschenbomben zu zünden.\n\nSeid Ihr bereit? FÜR DIE HORDE!", sourceObjective = "Werdet Zeuge der Sturmlanzenapokalypse.", completion = "Die Finger sind zerstört, die Hand ist zerschlagen. Jetzt werden sich die Sturmlanzen in ihre Höhle im Alteractal zurückziehen müssen.\n\n<Cromush spuckt aus.>\n\nKriegshäuptling Höllschrei wird von Eurem Mut erfahren, {name}.\n\nUnd Ihr könnt sicher sein, dass wir den Verrat des Frostwolfklans ebenfalls erwähnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28617] = { id = 28617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blumenkinder", description = "Ihr habt bereits gelernt, wie man die Speier verwendet, aber wusstet Ihr, dass alles schneller wächst, wenn man Sonnenblumen benutzt? Wir werden ein paar Sonnenblumen heranziehen und einige Speier pflanzen und damit Aufseher Stillwassers verrückte Monstrositäten aufhalten.\n\nLos!", sourceObjective = "Überlebt eine riesige Zombiewelle.", completion = "Ich glaube, das war erst der Anfang, Kumpel! NEUE WELLE!", sourceObjectiveStatus = "unverified-source-field" }
quests[28618] = { id = 28618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felslieferung", description = "Bitte sehr, wie versprochen! Ein Fels in einer Kiste.\n\nDarum hat Lilith doch gebeten, oder? Sie ist meine einzige Kundin!", sourceObjective = "Gebt einen Fels in einer Kiste bei Lilith der Lieblichen in der Ewigen Warte ab.", progress = "Oh, Ihr schon wieder. Wo ist der Fels?", completion = "Ah, Ihr habt tatsächlich einen Fels mitgebracht! Das überrascht mich etwas.\n\nTretet zurück und werdet Zeuge allerhöchster Handwerkskunst.", sourceObjectiveStatus = "unverified-source-field" }
quests[28619] = { id = 28619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Arathihochland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Dunkelläuferin Alina bei Galens Sturz zu melden. Die Streitkräfte der Dunklen Fürstin wollen das Herrschaftsgebiet der Horde vergrößern und die Allianz zurückschlagen. Helft ihnen dabei.\n\nDas Arathihochland liegt östlich des Vorgebirges des Hügellands. Folgt der Straße, die am Thoradinswall vorbeiführt.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Dunkelläuferin Alina bei Galens Sturz im Arathihochland.", completion = "Endlich ist die Verstärkung des Kriegshäuptlings eingetroffen. Die Dunkle Fürstin hat für Euch ebenso große Pläne wie für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28620] = { id = 28620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ostwachtturm", description = "In unserem Außenposten im Südosten gibt es einige Probleme. Mehr weiß ich auch nicht, nur... nun, ich werde Euch einfach aus dem letzten Brief vorlesen:\n\n\"Die Orcs werden bockig. Schickt Hilfe, sonst lasse ich sie mit Schilfrohr schlagen.\"\n\nDas ist alles. Der Brief stammt von unserem Chefpsylosophen Nils Bierwurz. Und nein, ich weiß auch nicht, was das heißen soll. Würdet Ihr bitte zum Ostwachttum reisen und herausfinden, was er braucht? Ich halte diese kryptischen Briefe nicht mehr aus!\n\nWendet Euch nach Süden und folgt dann der Straße nach Osten.", sourceObjective = "Sprecht mit Nils Bierwurz am Ostwachttum im Vorgebirge des Hügellands.", completion = "Endlich schickt dieser Schwachkopf Hilfe! Diesen beiden Orcs ist nicht mehr zu helfen. Sie leiden unter etwas, das ich \"Durnholdesyndrom\" nenne. Sie waren so lange eingekerkert, dass sie begonnen haben, Zuneigung für ihre Wärter zu empfinden. Sie sitzen mit ihren großen Eisenkugeln auf meinem Sofa und weinen.\n\nHoffentlich werdet Ihr Euch als nützlicher erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28621] = { id = 28621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt das Baby in die Wiege!", description = "Ach!\n\nIhr und Junior habt Euch ja schön viel Zeit gelassen, oder!?\n\n<Bier trinken/Händchen halten>, die Aussicht genießen - liege ich richtig?\n\nBrecht Euch nicht die Hand, wenn Ihr Euch auf die Schulter klopft. Die richtige Arbeit kommt erst noch!\n\nIn diesem alten Artefakt steckt mehr, als es den Anschein hat. Um seine Geheimnisse zu ergründen, müssen wir es zur Wiege der Uralten bringen!\n\nAber wie stellen wir das am besten an?\n\nVielleicht fällt Junior ja was Schlaues ein.", sourceObjective = "Sprecht mit Harrison Jones beim Tempel von Uldum.", completion = "Natürlich habe ich einen Plan, wie wir die Lade transportieren.\n\nVielleicht wird dieser alte Kautz ja eines Tages lernen, mir zu vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28622] = { id = 28622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein, zwei, nein, drei Signalleuchtfeuer", description = "Ich wollte die Lade eigentlich zur Untersuchung in mein Labor bringen, aber anscheinend hat Brann hier andere Pläne.\n\nEr meint, zu wissen, wie wir Todesschwinges Pläne hier in Uldum durchkreuzen können.\n\nMein Kumpel Jock wartet nur auf unser Signal, um mit dem Transport zu beginnen.\n\nNehmt diese Signalleuchtfeuer und stellt sie um den Tempel herum auf, damit er weiß, dass wir bereit sind.", sourceObjective = "Benutzt die Signalleuchtfeuer beim Tempel von Uldum.", completion = "Gute Arbeit, mein Freund.\n\nAnscheinend haben alle die Reise überstanden.\n\nSo langsam verstehe ich, warum Ihr Junior begleiten dürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28623] = { id = 28623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Westen", description = "Unsere Arbeit hier ist getan, {name}. Obwohl alles gegen uns sprach, konnten wir einen Vorstoß der Neferset auf Nahom verhindern.\n\nWir sollten uns den Streitkräften anschließen, die den Kampf nach Westen tragen, sonst streichen sie all den Ruhm allein ein.\n\nWahrscheinlich haben sie schon die Randgebiete von Neferset erreicht.", sourceObjective = "Meldet Euch bei König Phaoris in den Außenbezirken von Neferset in Uldum.", completion = "Ihr seid gerade rechtzeitig eingetroffen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28624] = { id = 28624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kilrams Prahlerei", description = "Pah! Primitiv und schwerfällig, was anderes kann ich dazu nicht sagen!\n\nStärke ist nicht alles. Meine Äxte sind so stark wie Liliths Streitkolben, aber so scharf, dass ich einen Baum mit einem Schlag fällen kann!\n\nIhr habt es gehört. Ein Schlag! Ich werde es Euch vor allen hier beweisen. Geht zu Deez. Er soll einen Baum herbringen!", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Jetzt wollen sie einen Baum? Mal sehen, was ich habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28625] = { id = 28625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baum fällt!", description = "Ich handle viel mit Brettern, aber komplette Bäume? Das wird selten verlangt. Ebenso wie Felsen.\n\nVielleicht könnt Ihr mir ja noch einen Gefallen erweisen. Westlich der Stadt gibt es einen Hain, von dem aus man den Kel'Therilsee sehen kann. Ich weiß nicht, ob es an den Geistern liegt oder an all dem magischen Elfenmüll, der überall herumliegt, aber in letzter Zeit tauchen dort Treants und Peitscher auf.\n\nSeit sie dort sind, macht es keinen Spaß mehr, Holz zu fällen, also warum fällt Ihr sie nicht stattdessen? Bringt mir das Holz der Treants.", sourceObjective = "Beschafft 10 Stücke frischgeschlagenes Frostholz von Frostlaubtreants.", progress = "Zeigt mir das Holz.", completion = "Das ist eine ordentliche Ladung. Vielleicht sollten wir anfangen, Treants anstatt Bäumen zu pflanzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28626] = { id = 28626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumlieferung", description = "Bitte sehr, ein Wunderwuchs-Instantbaum, hergestellt mit 80% natürlicher Zutaten!\n\nKeine Wurzel, keine Nuss, kein Verdruss. Gebt ihn Kilram und sorgt dafür, dass er ein ordentliches Stück zurücktritt, bevor er ihn benutzt.", sourceObjective = "Bringt den Wunderwuchs-Instantbaum zu Kilram im Gasthaus der Ewigen Warte.", progress = "Zack zack!", completion = "Also gut! Bleibt zurück und seht Euch an, was eine Waffe von gehobener Qualität anrichten kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[28627] = { id = 28627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serils Prahlerei", description = "Wilde und Amateure.\n\nEs spielt keine Rolle, wie scharf oder schwer eine Waffe ist, wenn man damit nur herumfuchteln kann wie ein Oger. Ich könnte versuchen, Dinge wie Raffinesse und Geschwindigkeit, Balance und Kontrolle zu erklären... aber diese Narren werden das nur verstehen, wenn ich es ihnen zeige.\n\nSagt Deez, dass wir noch eine Lieferung von ihm benötigen. Ich brauche einen Eisblock.", sourceObjective = "Sprecht mit Deez Felsklau.", completion = "Oh, Ihr schon wieder! Was für eine Überraschung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28628] = { id = 28628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eislieferung", description = "Also gut, ein 100% reiner Soforteisblock von höchster Qualität!\n\nIch habe versucht, die Kunden eine Weile lang zum Schutz zu verkaufen. Ihr wisst schon, wie dieser Trick, den Magier drauf haben? Die Sache mit dem \"Atmen\" habe ich nur nie hinbekommen.", sourceObjective = "Bringt den Soforteisblock zu Seril Geißelbann in der Ewigen Warte.", progress = "Ah, da seid Ihr ja!", completion = "Perfekt. Jetzt werdet Ihr sehen, worauf es bei einer Waffe ankommt... Raffinesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[28629] = { id = 28629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Meine Freunde haben immerzu tolle Ideen. Ich habe nie das Gefühl gehabt mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nIch brauche dickes Yetifell von Eisdistelyetis. Ihr werdet sie südöstlich von hier in den Eisdistelbergen finden.", sourceObjective = "Erbeutet 10 dicke Yetifelle von Eisdistelyetis.", progress = "Für den Anfang habe ich mehr als genug. Bitte bringt mir die Felle so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, {name}. Damit haben wir einen guten Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[28630] = { id = 28630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo Drei", description = "Oben in den Eisdistelbergen sind zahlreiche Goblins verschwunden. Beinahe wäre mir das auch passiert!\n\nIch bin auf die Idee gekommen, einen Sensor zu installieren, der uns warnen sollte, wenn die Yetis sich der Ewigen Warte nähern. Natürlich funktioniert der auch nicht. Die Hügel sind voller Yetis, aber ich habe noch keinen Laut von ihm gehört.\n\nWürdet Ihr ihn für mich überprüfen? Vielleicht lässt er sich reparieren. Echo Drei steht südöstlich von hier, am Rand der Eisdistelberge. Fragt nicht, was aus Echo Eins und Zwei geworden ist.", sourceObjective = "Findet Echo Drei.", completion = "Ein Teil der Maschine bewegt sich noch, aber als Ihr genauer hinseht, bemerkt Ihr, dass sie stark beschädigt ist. Das Metall ist verbogen und aufgerissen. Riesige Fußabdrücke sind rund herum im Schnee zu sehen.\n\nUnd es klingt, als nähere sich etwas in diesem Moment...", sourceObjectiveStatus = "unverified-source-field" }
quests[28631] = { id = 28631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekte Hörner", description = "Ich kann doch keinen Yeti ohne Hörner machen!\n\nSeit einer Ewigkeit suche ich schon nach den perfekten Hörnern... aber die, die ich finde, sind nicht gut genug! Vor ein paar Tagen habe ich jedoch den größten Yeti in ganz Winterquell gesehen.\n\nIch nenne ihn Eisklatscher. Seine Hörner wären genau richtig! Er lauert ganz hinten in der Höhle auf dem östlichen Kamm der Eisdistelberge.\n\nBringt mir seine Hörner... aber vergesst nicht, Echo Drei auf dem Weg zu überprüfen!", sourceObjective = "Erbeutet Eisklatschers makellose Hörner.", progress = "Sind sie perfekt? Das hoffe ich!", completion = "Ich kann es gar nicht erwarten, das meinen Freunden zu zeigen! Also, wartet einen Moment, während ich die hier befestige... \n\nPerfect!", sourceObjectiveStatus = "unverified-source-field" }
quests[28632] = { id = 28632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch von den Hügeln", description = "Dieses Mal soll es Eis sein? Klar, was auch sonst. Ich habe gute und schlechte Nachrichten für Euch.\n\nDie guten: Es gibt reines, festes Eis in der Höhle in den Eisdistelbergen, östlich der Ewigen Warte. Die schlechten: Leider gibt es da auch jede Menge grausamer Yetis.\n\nAber wenn Ihr mit Yetis fertigwerdet, ist das ein Kinderspiel! Geht einfach zu den größeren Brocken und zerschlagt sie mit Eurer Waffe. Bringt alles hierher und überlasst mir den Rest.", sourceObjective = "Besorgt 7 Stücke reines Gletschereis aus der Höhle in den Eisdistelbergen.", progress = "Oh, Ihr seid zurück! Wie lief es mit den Yetis?", completion = "Nicht schlecht! Dann hoffen wir mal, dass sie als nächstes nicht um Lava bitten, richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[28633] = { id = 28633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lade der Verheißung", description = "Ich bin mir nicht sicher, was uns hier erwartet, also haltet die Augen offen.\n\nDiese Codes sollten uns den wahren Zweck der Lade enthüllen und uns Werkzeuge in die Hand geben, mit denen wir die Pläne, die Todesschwinge für Uldum hat, endgültig durchkreuzen können!\n\nBleibt zurück!", sourceObjective = "Gebt Brann Bronzebart den Inhalt der Lade der Verheißung.", progress = "Also dann.\n\nSeht Euch das an!?", completion = "Natürlich! Ich hatte geahnt, dass wir das finden würden.\n\nAllerdings überraschen mich die organischen Transformationen doch ein wenig.\n\nIn diesem alten Relikt steckt mehr, als ich zu hoffen gewagt hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[28634] = { id = 28634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung", description = "Eulenbestien... Seelenlose, gefiederte Monstrositäten, die den dunkelsten Tiefen des Wirbelnden Nethers entstiegen sind, um den Schwachen nachzustellen.\n\n<Nils zeigt auf die Wälder, die den Ostwachttum umgeben.>\n\nSie kreisen uns ein und sie planen einen Angriff - ich spüre es. Haltet sie auf, bevor sie eine Strategie entwickeln.\n\nGeht in den Wald und tötet jede Eulenbestie, die Ihr seht. KEINE DARF ÜBERLEBEN!", sourceObjective = "Tötet 12 tobende Eulenbestien.", completion = "Das Jucken hat aufgehört - erst einmal - aber sie werden zurückkehren.\n\nOh ja, das werden sie...", sourceObjectiveStatus = "unverified-source-field" }
quests[28635] = { id = 28635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespenstischer Hügellandhof", description = "Der Kampf um Dun Garok war der blutigste in der Geschichte der Hügellandschlachten. Die Zwerge standen vor einer zehnfachen Übermacht, kämpften aber bis zum bitteren Ende. Sie alle starben bei der Verteidigung dieses Stück Landes.\n\nNun heißt es, dass es dort spukt. Niemand traut sich heran! Dummerweise habe ich den Befehl erhalten, Dun Garok für eine Besiedlung vorzubereiten.\n\nWürdet Ihr mir den Gefallen erweisen, nach Dun Garok zu gehen und nach Beweisen für diese Geister zu suchen? Dun Garok liegt weit im Südosten.", sourceObjective = "Sucht in Dun Garok nach Beweisen für Geister.", completion = "Geister? Das kann man wohl sagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28636] = { id = 28636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schweigen der Zwerge", description = "Die Geister meiner Soldaten spuken in diesem Fort, <Junge/Mädchen>. Ihre Seelen sind an diesen Ort gebunden. Selbst im Tod kämpfen sie weiter für ihn. Traurig.\n\nMacht ihrem Leid ein Ende, dann könnt Ihr den Sieg Eures Volks vielleicht genießen.", sourceObjective = "Tötet 10 Geister von Dun Garok.", completion = "Selbst nach dem Tod kämpfen sie noch für ihr Land - so wie die Verlassenen. Ich werde der Kommandozentrale melden, dass Dun Garok unbewohnbar ist. Sie sollen behalten, was ihnen so am Herzen liegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28637] = { id = 28637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhunger", description = "Habt Ihr jemals Bärenfleisch probieren dürfen? In Gilneas hatte ich nie Gelegenheit dazu, aber die Bären hier sind wahre Delikatessen.\n\nDas Fleisch der Splitterzahnbären, die südlich von hier umherziehen, ist durch die Kälte gut mit Fett durchsetzt. Ich habe sie schon selbst gejagt, was ein ziemlicher Jux ist, aber noch lieber esse ich sie!\n\nWarum probiert Ihr die Jagd nicht einmal aus? Konzentriert Euch auf die Splitterzahnbären mit weißem Fell. Der Hauptmann wird alle, die Ihr tötet, hierher bringen.", sourceObjective = "Tötet 15 Splitterzahnbären.", sourceObjectiveStatus = "unverified-source-field" }
quests[28638] = { id = 28638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eulen sind die besten", description = "Ich habe mein ganzes Leben lang Eulen gegessen. Eulen schmecken gut, mein Freund Jez findet das auch. Ich habe ihm als erster vorgeschlagen, Eule zu verkaufen!\n\nDer hochwohlgeborene Worgen da vorn behauptet, Bär schmecke besser, aber ignoriert ihn einfach. Jagt erst einmal selbst ein paar Eulen. Südlich von hier gibt es jede Menge. Haltet Euch erstmal an die grauen und meldet Euch bei mir mit dem kleinen Sprechgerät, das Jez Euch gegeben hat, wenn Ihr ein paar zusammen habt.", sourceObjective = "Tötet 15 Winterquelleulen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28639] = { id = 28639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius", description = "Es heißt ja, man ist, was man isst. Ich weiß nicht, ob ich das glauben soll, aber wenn es stimmt... Also dann will ich die stärkste Kreatur essen, die ich finden kann.\n\nUrsius ist der größte Bär in ganz Winterquell. Er frisst als erster, wenn sein Rudel Splitterzähne eine Schimäre oder einen Eulenbär tötet. Ihm gehört die gemütlichste Höhle im Land der Splitterzähne. Und er hat... bemerkenswerten Einfluss auf die Weibchen der Splitterzähne.\n\nSo ein Bär gefällt mir.\n\nIch will ihn essen.\n\nSeine Höhle liegt in der Nähe der Raufer. Viel Glück!", sourceObjective = "Tötet Ursius.", completion = "Ursius schmeckt... nicht gerade köstlich. Sein Geschmack erinnert mich an eine Mischung aus Tannenzapfen und saurer Milch, nur... öliger.\n\nUnd Ihr seid sicher, dass das Ursius ist? Der große Bär? In der Höhle?\n\nDas ist furchtbar. Das Fleisch schmeckt so, als habe man es in Urin eingelegt.\n\nIch fühle mich nicht stärker.\n\nBah. Das ist wirklich übel. Wollt Ihr mal probieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[28640] = { id = 28640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Frostsäbler", description = "Riecht das nicht gut? Mein geräuchertes Fleisch bringt die höchsten Preise. Niemand außer mir bietet die exotischen Geschmackserlebnisse, die es hier in den Hügeln gibt. Und es ist sehr effizient. Ihr geht gegen ein kleines Entgelt auf die Jagd und meine guten Freunde bringen die Bestien hierher, wo sie gehäutet und geräuchert werden!\n\nIch beherrsche den Markt für Frostsäblerfleisch momentan. Unglaublich leckeres Zeug, aus dem man gute Würste machen kann. Zieht los und jagt die Katzen westlich von hier. Das ist ein guter Anfang!", sourceObjective = "Tötet 15 Frostsäbler oder Frostsäblerpirscherinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28641] = { id = 28641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzenburger", description = "Also gut, <Kleiner/Kleine>, jetzt geht es weiter nach draußen!\n\nDiese Lieferung war nicht schlecht, aber weiter westlich gibt es wesentlich größere Kätzchen. Die Rudelbehüterinnen und Jägerinnen sind wesentlich muskulöser. Hamburger aus ihrem Fleisch schmecken PHANTASTISCH. Sie verkaufen sich wie verrückt!\n\nGebt mir kurz Bescheid, wenn Ihr fertig seid, dann lassen wir Euch auf den Hauptgang los.", sourceObjective = "Tötet 15 Frostsäblerjägerinnen oder Rudelbehüterinnen der Frostsäbler.", sourceObjectiveStatus = "unverified-source-field" }
quests[28643] = { id = 28643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Zephyrus", description = "Burg Durnholde war stets ein Ort des Unfriedens. Jahrelang benutzten die Menschen sie als Internierungslager und Gefängnis für die Orcs. Danach wurde sie vom Syndikat übernommen. Und jetzt? Die Dunkle Fürstin hat mächtige Elementare gefangen und innerhalb ihrer Mauern ausgesetzt. Sie hat mir die Leitung der \"Herausforderung von Durnholde\" übertragen. Wer alle Elementare besiegt, erhält eine große Belohnung! Nehmt dieses Handbuch und stellt Euch Eurer ersten Herausforderung: Zephyrus!\n\nDurnholde liegt nordöstlich von uns.", sourceObjective = "Tötet Zephyrus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28644] = { id = 28644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Teracula", description = "Das Handbuch benennt Teracula als Eure nächste Herausforderung. Er folgt dem Pfad vor Zephyrus' Versteck.", sourceObjective = "Tötet Teracula.", sourceObjectiveStatus = "unverified-source-field" }
quests[28645] = { id = 28645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Blutgift", description = "Das Handbuch benennt Blutgift als Eure nächste Herausforderung. Dieser furchterregende Elementar hält sich auf der unteren Ebene der Burg Durnholde, nahe des westlichen Gefängnisses auf.", sourceObjective = "Tötet Blutgift.", sourceObjectiveStatus = "unverified-source-field" }
quests[28646] = { id = 28646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: Infernus", description = "Das Handbuch benennt Infernus als Eure nächste Herausforderung. Diesen Alptraum aus geschmolzener Lava und wütenden Flammen findet Ihr auf der unteren Ebene der Burg Durnholde, nahe des östlichen Gefängnisses.", sourceObjective = "Tötet Infernus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28647] = { id = 28647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung von Durnholde: D-1000", description = "Ein Wesen, das aus reinem Quecksilber besteht, wird in der alten Arena der Burg Durnholde gefangen gehalten. Die Verlassenen nennen es den D-1000. Tötet den D-1000 und holt Eure Belohnung ab!", sourceObjective = "Tötet den D-1000.", completion = "Noch nie zuvor hat jemand die Herausforderung abgeschlossen. Ihr seid ein wirklich mächtiger {class}, {name}. Wie versprochen könnt Ihr Euch eine Belohnung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28649] = { id = 28649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, zerlegten alles und machten uns auf den Weg zum Zellenblock. Wir haben nicht mit dem gerechnet, was wir dort fanden, {name}. Der Kreuzzug hat ganze Arbeit geleistet. Da sitzen jede Menge Gefangene der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, aber ein paar haben noch geatmet.\n\nIch wollte den Rest eigentlich selbst hinrichten, aber ich denke, die Ehre gebührt Euch. Vor allem den angriffslustigen Worgen, der dort sitzt, werdet Ihr bestimmt mit großer Freude hinrichten.", sourceObjective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Lord Harford, im nahegelegenen Gefängnis hinzurichten.", completion = "Das war doch gut, oder? Ihr gehört jetzt nicht mehr zu ihnen, {name}. Ihr seid jetzt bei der Geißel. Ihr seid auf ewig einer von uns...", sourceObjectiveStatus = "unverified-source-field" }
quests[28650] = { id = 28650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Als wir hier ankamen, haben wir alles auseinandergenommen und sind dann zum Gefängnis gezogen. Was wir dort fanden, hatten wir nicht erwartet, {name}. Es scheint, der Kreuzzug war sehr fleißig. Das ganze Ding ist voller Gefangener der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, doch ein paar atmeten noch.\n\nIch wollte gerade hingehen und den Rest umbringen, doch ich denke, Ihr solltet die Ehre haben. Es ist ein besonders aufmüpfiger Goblin darunter. Ich glaube, ihn zu richten wird Euch große Freude machen.", sourceObjective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Gally Klumpfleck, im nahegelegenen Gefängnis hinzurichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28651] = { id = 28651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novizin Elreth", description = "Jetzt, da die Ausbildung abgeschlossen ist, solltet Ihr mit Elreth sprechen. Sie dient Schattenpriester Sarvis. Wahrscheinlich hat sie einige Aufgaben, für die Ihr Eure neu erworbenen Fähigkeiten einsetzen könnt.", sourceObjective = "Sprecht mit Novizin Elreth in Todesend in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[28652] = { id = 28652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwalter Caice", description = "Ich brauche Euch nicht mehr. Es gibt jedoch andere, für die Eure Hilfe wichtig ist.\n\nVerwalter Caice auf dem Stumpf hinter mir wird Euch wohl einen Auftrag geben können. Sprecht jetzt mit ihm.", sourceObjective = "Sprecht mit Verwalter Caice an den Gräbern von Todesend in Tirisfal.", completion = "Ja, bitte? Und Ihr seid...?", sourceObjectiveStatus = "unverified-source-field" }
quests[28653] = { id = 28653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenpriester Sarvis", description = "Ihr seid noch immer hier, {name}? Ich bin ja leider nur eine Todeswache und habe kaum Aufgaben, die ich zufälligen Passanten geben kann.\n\nAm besten sprecht Ihr mit Schattenpriester Sarvis. Nachdem sie mich damals aus dem Grab geholt hatten, hat er mich wieder auf die Beine gebracht. Er tut das sicher auch für Euch.\n\nIhr findet ihn in der Kapelle, hier auf der Westseite der Stadt.", sourceObjective = "Sprecht mit Schattenpriester Sarvis in Todesend in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[28654] = { id = 28654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pudels Kern", description = "Ich würd' ja gern noch ein Weilchen bleiben und mit Euch in die Gegend schauen, <Bürschchen/Mädel>.\n\nAlso, ich hab' bestimmt schon die tollsten Dinger gesehn, aber so was ist mir mein Lebtag noch nicht untergekommen.\n\nLeider muss ich diese Scheiben noch gründlicher untersuchen, eh' ich mich zu den Hallen des Ursprungs aufmachen kann.\n\nIch glaub', Ihr seid schwer in Ordnung. Wollt Ihr mal sehen, wie ein richtiger Archäologe arbeitet? Dann kommt mit!", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn in den Hallen des Ursprungs trefft.", completion = "Höchste Zeit, dass Ihr eintrefft, Bursche.\n\nAuf geht's! An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28655] = { id = 28655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Wildhammer-Hochzeit", description = "Wir sind bereit, {name}!\n\nIch weiß aber aus sicherer Quelle, dass der Schattenhammer versuchen wird, die Zeremonie zu vereiteln. Damit soll der Wildhammer demoralisiert und zerstört werden. Es kann gefährlich werden!\n\nDeshalb werde ich die Zeremonie selbst vollziehen und Braut und Bräutigam in nächster Nähe behalten. Klingt das gut? Bestens!\n\nDa Fannys Vater nicht mehr lebt und ihr Bruder Trauzeuge des Bräutigams ist, bittet sie darum, dass Ihr sie an den Altar geleitet. Welch eine Ehre! Gebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Sagt Grundy MacGraff, dass die Hochzeitszeremonie beginnen kann. Tötet jeden Schattenhammer, der versucht, sie zu verhindern.", completion = "{name}, wir haben's geschafft! Wie alle Wildhämmer zusammen gegen dieses... Ding gekämpft haben - das hat sie so richtig zusammengeschweißt. Die Familienoberhäupter sind so einig wie nie zuvor. Zum Wohl, {name}, lasst uns feiern!!\n\nMit unserer Arbeit stehen wir natürlich noch ganz am Anfang. Ich lasse unsere neue Wildhammerverstärkung zum Rest der Allianz hinzustoßen und den Sturm der Bastion des Zwielichts vorbereiten.\n\nWir treffen uns bestimmt bald wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[28656] = { id = 28656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Lebenskräfte", description = "Beim Tod dieser Kreatur ist ihr eine Art Energie entstiegen. Diese Energie ist auf Euch übergegangen und so fühlt Ihr Euch etwas stärker.\n\nGlaubt man den Einwohnern von Winterquell, dann ist die Hexendoktorin Mau'ari an Schneewehs Berghütte eine Expertin für die Tierwelt dieser Gegend. Vielleicht weiß sie was über die geheimnisvolle Energie.", sourceObjective = "Begebt Euch zu Schneewehs Berghütte in Winterquell und sprecht dort mit Hexendoktorin Mau'ari.", completion = "Was'n das? Du riechst nach E'ko! Lass dir von Mau'ari mal was übers E'ko erzähl'n un' was es so tut.\n\nDu hast Glück, {race}. Das E'ko is' zu dir gekommen. Ein einfacher Troll wie ich muss selber E'ko such'n.\n\nDie Kreaturen von Winterquell hab'n alle E'ko. Die Furbolgs, die Schimären, die Splitterzähne... sogar die Eisdistelyetis! Wenn du so 'ne Kreatur tötest, kommt manchmal 'n bisschen E'ko 'raus. Verschiedene Kreaturen... verschiedenes E'ko.\n\nDann mal los. Such' weiter E'ko!", sourceObjectiveStatus = "unverified-source-field" }
quests[28657] = { id = 28657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein riesiges Problem", description = "Endlich haben wir diesen gottverdammten Fels eingenommen und dann treibt so ein riesiger Ettin hier sein Unwesen und schaltet unsere Wachpatrouillen aus!\n\n{name}, trommelt ein paar Verbündete zusammen und erledigt den Ettin. Wir können nicht zulassen, dass die Bestie hier alles verwüstet.\n\nSeid auf der Hut, von der Front wird gemeldet, dass er mit einem riesigen Baum bewaffnet ist. Und er hat keine Skrupel, ihn einzusetzen.", sourceObjective = "Ihr wurdet beauftragt, Problim zu töten, einen Riesenettin, der die Wege von Tol Barad unsicher macht.", completion = "Ihr habt ihn tatsächlich getötet?! Ich kann es kaum glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[28658] = { id = 28658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sumpfköder", description = "An solchen Orten ist die Versorgung immer schwer, {class}. Seit wir die Insel eingenommen haben, erkunden wir sie, aber es sieht nicht gut aus.\n\nZum Glück haben wir gerade erfahren, dass sich gleich westlich von unserem Basislager ein Sumpf voller Krokis befindet. Deren Bälge werden unseren Lederern gerade recht kommen. Bringt so viele her wie Ihr nur könnt.", sourceObjective = "Ihr habt den Auftrag, auf Tol Barad 8 Krokiliskenbälge von Krokilisken von Baradin zu besorgen. Die Krokilisken findet Ihr im Sumpf, gleich westlich der Baradinfestung.", progress = "Habt Ihr schon im Sumpf aufgeräumt?", completion = "Sieht aus, als habt Ihr die Krokibälge, die wir brauchen. Danke, {name}, Euer Beitrag wird Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28659] = { id = 28659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste", description = "Wir haben hart um diese Insel gekämpft, {race}. Den Großteil des Allianzdrecks haben wir rausgeschmissen, aber ihr übler Gestank liegt noch immer in der Luft.\n\nKundschaftet die Erzraffinerie, die Hüterwacht und die Eiserne Garnison aus. Tötet alle Angehörigen der Allianz, die Ihr findet.\n\nIhr kennt ja das Sprichwort: Nur ein toter Allianzler ist ein guter Allianzler!", sourceObjective = "Ihr habt den Auftrag, 12 Infanteristen der Allianz auf Tol Barad zu töten. In der Erzraffinerie, der Hüterwacht und der Eisernen Garnison hier auf Tol Barad sind noch Widerständler zu finden.", completion = "Dieser Allianzabschaum hatte nicht die geringste Chance. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28660] = { id = 28660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefen säubern", description = "Wie schön, Euch zu sehen, {name}. Jetzt, da wir Tol Barad eingenommen haben, fängt die Schlacht erst an.\n\nGleich östlich von hier haben wir einen Zellenblock entdeckt, den Ihr ausräumen müsst. Er steckt zum Bersten voll mit Geistern, die seit Ewigkeiten dort eingesperrt sind.\n\nBeseitigt so viele wie möglich und meldet Euch dann bei mir.", sourceObjective = "Ihr habt den Auftrag, 9 Geister beliebigen Typs in den Verfluchten Tiefen gleich östlich der Baradinfestung zu töten.", completion = "Ihr seid lebendig davongekommen? Ihr seid stärker als ich es bin, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28661] = { id = 28661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Erzmagier", description = "Seit wir auf Tol Barad gelandet sind, versuchen wir, den Zellenblock in den Verfluchten Tiefen auszuräumen. Jedes Mal, wenn wir uns nähern, taucht dieser Erzmagier auf und drängt uns zurück.\n\nJetzt, da wir die Insel eingenommen haben, ist es an der Zeit, es noch einmal zu versuchen. Begebt Euch dorthin und bringt mir seinen Stab zum Beweis, dass Ihr den Auftrag erledigt habt.", sourceObjective = "Ihr müsst Erzmagier Galus töten und mit seinem Stab aus den Verfluchten Tiefen östlich der Baradinfestung zurückkehren.", progress = "Konntet Ihr den Erzmagier beseitigen?", completion = "Galus ist tot? Fantastische Arbeit, {name}. Jetzt können wir die Putzkolonne dort hinunterschicken und den Zellenblock für neue Gefangene vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28662] = { id = 28662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Vergangenheit lernen", description = "Nun, da wir diese jämmerliche Insel endlich beherrschen, können wir herausfinden, was sie so zugerichtet hat. Einige unserer Kämpfer haben Tagebücher erspäht, gleich westlich von hier am Eingang zum Zellenblock der Verfluchten Tiefen.\n\nUnsere Schriftgelehrten im Basislager werden sich für diese Tagebücher ganz besonders interessieren. Ihr müsst vier davon an Euch bringen und mir so schnell wie möglich übergeben.\n\nSeid vorsichtig, {name}. Da unten wimmelt's nur so von Untoten.", sourceObjective = "Ihr habt den Auftrag, aus den Verfluchten Tiefen gleich östlich der Baradinfestung vier Verstaubte Gefängnistagebücher zu holen.", progress = "Seid Ihr im Besitz der Tagebücher? Die Meldungen besagen, dass sie in den Zellen und auch außerhalb gesichtet wurden.", completion = "Diese Tagebücher sind bestens erhalten, {name}. Wir machen uns sofort daran, sie zu entziffern. Die Zeit wird zeigen, welche Geheimnisse sie bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28663] = { id = 28663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Habt Ihr schon einmal von dem D-Block gehört, {name}? Das ist einer der Zellenblöcke hier auf der Insel. Das Problem ist, dass er von Dämonen befallen ist. Wir hatten eigentlich vor, dort die verbliebenen Mitglieder der Allianz einzusperren, die wir auf der Insel gefunden haben, aber in seinem momentanen Zustand ist das unmöglich.\n\nIhr müsst dort hinuntergehen und diese Dämonen beseitigen. Meldet Euch wieder bei mir, wenn Ihr das erledigt habt.", sourceObjective = "Ihr wurdet angewiesen, 10 beliebige Dämonen im D-Block, gleich nordwestlich der Baradinfestung, zu töten.", progress = "Sind die Dämonen schon erledigt? Wir warten auf Euch, {name}. Lasst mich wissen, wenn Ihr fertig seid.", completion = "Ist der D-Block ausgeräumt? Gute Arbeit, {name}. Wir schicken sofort einen Reinigungstrupp los.", sourceObjectiveStatus = "unverified-source-field" }
quests[28664] = { id = 28664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Ihr habt Hervorragendes für die Eroberung der Insel geleistet, {class}. Jetzt, da wir die Insel eingenommen haben, müssen wir die Zellenblöcke für die Gefangenen herrichten. Der D-Block war besonders schwer zu bereinigen. Leider wimmelte er nur so von Dämonen aller Art.\n\nWir konnten einige beseitigen, doch dann brach ein großer Kernhund aus seiner Zelle aus - er verwüstet dort alles. Tötet ihn und bringt mir sein Halsband.", sourceObjective = "Ihr müsst Svarnos im D-Block töten und sein verfluchtes Halsband herbringen. Svarnos befindet sich im D-Block, gleich nordwestlich der Baradinfestung.", progress = "Ist der Kernhund tot?", completion = "Svarnos ist wirklich tot? Sieht aus, als könnten wir endlich loslegen und den Zellenblock herrichten. Danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28665] = { id = 28665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Fesseln", description = "Wart Ihr schon im D-Block, {name}? Wenn der verseuchte Zellenblock gerade frei ist, sind die Dämonen jedes Mal ganz schnell wieder drin. Man sagte uns, sie regenerieren sich aus den im Gelände verstreuten Verfluchten Fesseln. Da ist Euer Einsatz gefragt, {name}.\n\nIhr müsst so viele Verfluchte Fesseln wie möglich einsammeln und herbringen. Wir zerstören sie dann sofort.", sourceObjective = "Ihr erhieltet den Auftrag, 8 Verfluchte Fesseln aus dem D-Block, gleich nordwestlich der Baradinfestung, zu holen.", progress = "Habt Ihr viele Fesseln gefunden? In den Meldungen hieß es, sie seien dort überall verstreut.", completion = "Die Fesseln! {name}, wir fangen sofort damit an, diese Fesseln zu zerstören. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28666] = { id = 28666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Brennende Steppe!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei John J. Keeshan am Flammensternposten zu melden.\n\nIhr müsst dringend helfen, der Bedrohung durch die Schwarzfelsorcs ein Ende zu bereiten!\n\nDer Weg zur Brennenden Steppe führt südlich der Sengenden Schlucht durch den Schwarzfels. Haltet Ausschau nach dem Flammensternposten auf der anderen Seite des Schwarzfels.\n\nRuhm und Ehre der Allianz!", sourceObjective = "Meldet Euch bei John J. Keeshan am Flammensternposten in der Brennenden Steppe.", completion = "Höchste Zeit, dass die Schwarzfelsorcs den ganzen Zorn der Allianz zu spüren bekommen. Jetzt werden sie für ihre Untaten büßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28667] = { id = 28667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Brennende Steppe!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Ariok am Flammensternposten zu melden.\n\nUnterstützt Etriggs geehrten Sohn Ariok und haltet die blinde Aggression der Schwarzfelsorcs auf, ehe sie die Nachbarländer besetzen.\n\nDer Weg zur Brennenden Steppe führt südlich der Sengenden Schlucht durch den Schwarzfels. Der Flammensternposten ist südlich vom Schwarzfels.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Ariok am Flammensternposten in der Brennenden Steppe.", completion = "Wir müssen die Schwarzfelsorcs stoppen, bevor sie ihren Einflussbereich ausdehnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28668] = { id = 28668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangenenaufstand", description = "Die Insel gehört uns. Jetzt müssen wir unsere Anlagen hier einsatzbereit machen. Wir haben einen aufgegebenen Zellenblock südwestlich von hier gefunden und wir müssen ihn auskundschaften, {name}.\n\nBerichten zufolge ist er voller Gefangener, die dort drinnen seit Jahren festsitzen. Tut, was immer ihr müsst, um den Ort zu säubern. Meldet Euch bei mir, wenn Ihr fertig seid.", sourceObjective = "Ihr wurdet beauftragt, 10 beliebige Gefangene im Loch zu töten, das südwestlich der Baradinfestung liegt.", completion = "Ihr habt das Gebiet gesäubert? Es sieht so aus, als ob Ihr Euch als nützlicher erweist, als wir dachten, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28669] = { id = 28669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wärter", description = "Wir haben es fast geschafft, die aufständischen Gefangenen im Loch zu beseitigen, doch ein Problem bleibt: Der Wärter.\n\nWärter Silva ist ihr Meister. Für ihn tun sie alles. Wenn wir ihn ausschalten, schalten wir alle aus. Tötet ihn und bringt mir seine Schlüssel. Mit den Schlüsseln können wir den Zellenblock weiter erkunden und hoffentlich auch zur Wasserversorgung der Insel vordringen.", sourceObjective = "Tötet Wärter Silva im Loch und kehrt mit seinen Schlüsseln zurück. Das Loch ist südwestlich der Baradinfestung.", progress = "Ist der Wärter endlich tot?", completion = "Aah, die Schlüssel des Wärters. Wieder einmal habt Ihr gute Arbeit geleistet, {name}. Diese Schlüssel werden sich noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28670] = { id = 28670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen von unten", description = "Uns gehen die Vorräte im Lager aus, {name}. Wir haben vor Kurzem von einem Zellenblock südwestlich von hier gehört, in dem nach jahrelangem Betrieb noch Rationen übrig sind. Wir brauchen so viele Rationen wie ihr tragen könnt hier im Lager.\n\nOh, und noch etwas: in dem Zellenblock wimmelt es von Gefangenen, also seid vorsichtig.", sourceObjective = "Ihr wurdet gebeten, 12 Rationen aus dem Zellenblock aus dem Loch südwestlich der Baradinfestung zu besorgen.", progress = "Konntet Ihr die Rationen ausfindig machen? Berichten zufolge kann man sie über den ganzen Ort verteilt finden.", completion = "Die Rationen werden unseren Truppen sehr helfen, {name}. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28671] = { id = 28671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Verwüstete Lande!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Okrilla an der Feste Schreckensfels zu melden.\n\nOkrilla, Kommandantin der Hordenstreitmacht an der Feste Schreckensfels braucht Eure Hilfe bei der Sicherung des Außenpostens vor rebellischen Ogern und der Streitmacht der Allianz.\n\nZieht zur Feste Schreckensfels auf der Straße südlich der Sümpfe des Elends.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28672] = { id = 28672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exekutor im Feld", description = "Ich kann Euch die ganze Woche hier in der Stadt beschäftigen... aber Ihr scheint mir mehr der Kämpfertyp zu sein.\n\n<Elreth nimmt Euch in Augenschein und nickt.>\n\nJa, Ihr seid in Ordnung. Bitte sprecht mit Exekutor Arren. Folgt dem Pfad, der aus Todesend nach Norden herausführt. Ihr findet ihn kurz hinter den Barrikaden.", sourceObjective = "Meldet Euch bei Exekutor Arren.", completion = "Was haben wir denn hier? Ein frischgebackener {class}, der in den Kampf ziehen will, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[28673] = { id = 28673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Verwüstete Lande!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rüstmeister Lungertz an der Burg Nethergarde zu melden.\n\nDie Garnison von Nethergarde benötigt dringend Eure Hilfe, um den Vormarsch der Horde in die Verwüsteten Lande zu stoppen! Zieht von den Sümpfen des Elends aus nach Süden und folgt der Straße nach Osten zur Burg Nethergarde.\n\nRuhm und Ehre der Allianz!", sourceObjective = "Meldet Euch bei Rüstmeister Lungertz in der Burg Nethergarde.", completion = "Über Jahrzehnte hat die Garnison in Nethergarde der Bedrohung durch die Horde standgehalten und auch jetzt werden wir uns nicht ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28674] = { id = 28674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternfall", description = "Ihr habt Euch hier in der Gegend ja ganz schön nützlich gemacht. Wenn Ihr noch an guten Werken oder Eurer Bezahlung interessiert seid, dann habe ich hier etwas für Euch.\n\nSternfall liegt direkt im Nordwesten der Ewigen Warte. Die Nachtelfen dort klagen über starken Insektenbefall und bitten dringend um Hilfe.\n\nEin paar Goblins von hier sind schon losgezogen, um mit dem Ausrotten zu beginnen. Aber es ist sicher noch Platz für Euch. Sprecht mit Wynd Nachtjagd, er sagt Euch alles Wichtige.", sourceObjective = "Sprecht mit Wynd Nachtjagd in Sternfall.", completion = "Willkommen in Sternfall, {class}. In dieser Zeit der Not öffnen wir unsere Tore allen Reisenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28675] = { id = 28675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Sümpfe des Elends!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Handelsbaron Silberschnapp in Kraulsumpf zu melden.\n\nDie Kräfte der Allianz brauchen dringend die vom Baron beschaffte Munition! Tut alles Nötige, um den Baron zu überzeugen, unsere Kräfte auch weiterhin zu vernünftigen Preisen zu versorgen.\n\nUm zu den Sümpfen zu gelangen, folgt Ihr der Straße von den südöstlichen Brennenden Steppen durch das Rotkammgebirge.\n\nRuhm und Ehre der Allianz!", sourceObjective = "Meldet Euch bei Handelsbaron Silberschnapp in Kraulsumpf in den Sümpfen des Elends.", completion = "Willkommen in Kraulsumpf, {class}. Ich bin sicher, Ihr werdet all unsere Annehmlichkeiten in vollen Zügen genießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28676] = { id = 28676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kammerjäger am Werk", description = "Unser Grabhügel wurde praktisch über Nacht befallen. In diesen Landen unbekannte, heimtückische Kreaturen sind aus unsichtbaren Eiern geschlüpft und sind in die Tunnel ausgeschwärmt.\n\nWir sind nur Wenige. So haben wir nichts weiter tun können, als ihr Vordringen aus dem Hügel zu verhindern. Wir waren gezwungen, Goblins aus der Ewigen Warte anzuheuern. Sie behaupten, Ausrottungsexperten zu sein, doch bisher haben sie keinen Erfolg gehabt.\n\nWenn Ihr sie unterstützen wollt, dann betretet den Grabhügel westlich von dieser Hütte und sprecht mit Rinno Vorhangfeuer.", sourceObjective = "Sprecht mit Rinno Vorhangfeuer im Grabhügel von Ban'Thallow.", completion = "Sehr gut, noch jemand zum mit Anpacken!\n\nIch hoffe nur, der Elf oben hat Euch nicht zu Tode gelangweilt. Wir haben hier eine Menge Ungeziefer zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28677] = { id = 28677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Sümpfe des Elends!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Handelsbaron Silberschnapp in Kraulsumpf zu melden.\n\nÜberzeugt den Handelsbaron, unsere Krieger weiterhin mit Waffen und Munition zu versorgen. Alle Mittel sind recht!\n\nZu den Sümpfen des Elends gelangt Ihr über die Straße von den südöstlichen Brennenden Steppen durch das Rotkammgebirge. Besucht den Handelsbaron in seinem Seebad. \n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Handelsbaron Silberschnapp in Kraulsumpf in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[28678] = { id = 28678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän P. Harris", description = "Das Kap der Verlorenen Hoffnung steckt uns hier auf Tol Barad seit Wochen wie ein Stachel im Fleisch. Die Hälfte unserer Versorgungsschiffe endet auf den Felsen dort unten.\n\nHinzu kommt, dass es von einer Bande untoter Matrosen überrannt wurde. Wir haben versucht, sie zu dezimieren, aber sie kommen immer wieder zurück. Unsere letzte Hoffnung ist es, den Kapitän zu töten, der ihnen ihre Befehle gibt. Ihr solltet ihn auf einem Schiff nahe des Ufers finden.\n\nOh, und ich hoffe, Ihr habt keine große Angst vor Haien.", sourceObjective = "Ihr habt den Auftrag, Kapitän P. Harris am Kap der Verlorenen Hoffnung zu töten. Das Kap der Verlorenen Hoffnung liegt gleich nordwestlich von hier, die Küste entlang. Haltet einfach Ausschau nach den Schiffswracks.", progress = "Habt Ihr den riesigen Hai da draußen gesehen? Ich würde mich ihm nicht weiter als 50 Meter nähern, wenn ich Ihr wäre.", completion = "Ihr habt es geschafft! Vielleicht schaffen es jetzt endlich ein paar Schiffe in den Hafen! Danke sehr, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28679] = { id = 28679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stört ihre vorletzte Ruhe", description = "Seit einiger Zeit haben wir Probleme mit den Untoten unten am Kap der Verlorenen Hoffnung. Bei jedem neuen Schiffbruch schließen sich ihnen neue Untote an.\n\nKönnt Ihr uns einen Gefallen tun und die Mannschaft dort etwas ausdünnen? Ich weiß, Ihr könnt sie nicht alle töten, aber jeder Beitrag ist für uns von Nutzen.\n\nHaltet ein Auge auf die Allianz, in letzter Zeit wird gemeldet, dass ihre Kämpfer am Strand im Hinterhalt liegen.", sourceObjective = "Dritter Offizier Kronkar hat Euch beauftragt, 8 schiffbrüchige Seemänner am Kap der Verlorenen Hoffnung zu töten. Das Kap liegt genau im Nordwesten von hier am Strand.", completion = "Gute Arbeit mit den Untoten da oben, {name}. Wir wissen Eure Hilfe wirklich sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28680] = { id = 28680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkung der Moral", description = "Unsere Kampfmoral ist geschwächt, {name}. Wir tun alles, um den Kampfgeist der Truppen zu stärken, doch unser wichtigstes Mittel geht zur Neige. Ich spreche vom Rum.\n\nUnsere Infanterie meldet aus dem Süden, dass die Schiffswracks am Kap der Verlorenen Hoffnung beträchtliche Mengen an Südseerum gebunkert haben. Könnt Ihr Euch dorthin begeben und dem nachgehen?\n\nBringt so viel Rum her, wie Ihr nur könnt.", sourceObjective = "Ihr habt den Auftrag, aus den Schiffswracks am Kap der Verlorenen Hoffnung 6 Fässer Südseerum zu beschaffen. Das Kap liegt nördlich von hier, an der Küste.", progress = "Habt Ihr den Rum zurückholen können? Ich würde es ja versuchen, aber ich habe Todesangst vor dem Wasser. Ganz zu schweigen von dem verrückten Hai.", completion = "Der Rum hilft uns sehr, {name}. Auch wenn's ihnen morgens nicht so gut geht, wenigstens schlafen sie glücklich ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28681] = { id = 28681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank, der Haifisch", description = "Ich hasse Haie. Und meine Truppen auch. Deshalb brauchen wir Euch, {name}.\n\nIhr müsst Euch zum Kap der Verlorenen Hoffnung begeben und einen riesigen Haifisch namens Tank zur Strecke bringen. Tank ist nicht auf die leichte Schulter zu nehmen. An Eurer Stelle würde ich ein paar Freunde mitnehmen.", sourceObjective = "Ihr müsst Tank, den großen Hai, der die Gewässer des Kaps der Verlorenen Hoffnung unsicher macht, töten. Das Kap liegt nördlich von hier, an der nördlichen Küste.", completion = "Das gibt's doch nicht - Ihr habt ihn wirklich getötet? Oh ja - und heut' Abend gibt's Haifischbraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28682] = { id = 28682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einnahme der Festung", description = "Habt Ihr die Festung im Norden der Insel gesehen, {name}? Von dort aus koordiniert Festungslord Farson seine Kriegszüge.\n\nFarson verfügt über einen kleinen Trupp ergebener Gefolgsleute. Seit wir hier eintrafen, machen sie uns Ärger. Wir haben einen Erkundungstrupp vorausgeschickt, der uns seinen genauen Standort in der Festung gemeldet hat.\n\nKönnt Ihr ihn für uns erledigen?", sourceObjective = "Eure Aufgabe lautet, Festungslord Farson in der Farsonfestung zu töten. Die Farsonfestung befindet sich auf der Nordseite der Insel.", completion = "Habt Ihr ihn umgebracht? Mehrere Wochen haben wir schon versucht, ihn zu erledigen! Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28683] = { id = 28683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen der Brut", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl soweit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Allianzruppen dort gesichtet wurden.", sourceObjective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt nördlich von hier, jenseits der Brücke auf der mittleren Insel.", completion = "Den Spinnen habt Ihr es gezeigt, {name}. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[28684] = { id = 28684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine klebrige Angelegenheit", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide ausmachen können, im Finsterwald, direkt westlich von hier. Der Nachteil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", sourceObjective = "Sammelt 4 klebrige Seidendrüsen von Dunkelwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt gleich westlich von hier, hinter der Brücke in der Mitte der Insel.", progress = "Habt Ihr die klebrigen Seidendrüsen?", completion = "Diese Drüsen sind perfekt. Wir danken Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28685] = { id = 28685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keine Waffen zurück", description = "Auf diesem Felsen kommt man nur schwer an Kampfgerät. Jedes Mal, wenn wir die Allianz abwehren, kommt es uns vor, als kämpften wir mit Stöcken und Steinen.\n\nWir haben gehört, dass Festungslord Farson im Norden der Insel einen großen Vorrat an Gewehren hat. Könnt Ihr Euch dort hinbegeben und Euch darum kümmern?\n\nVorsicht, {name}, um Farson zu schützen, schreckt seine Gefolgschaft vor nichts zurück.", sourceObjective = "Beschafft 12 rostige Gewehre aus der Farsonfestung auf der Nordseite der Halbinsel von Tol Barad.", progress = "Wie läuft's mit den Gewehren?", completion = "Vielen Dank, dass Ihr die für uns aufgetrieben habt, {name}. Es ist wirklich kein Kinderspiel, eine Schlacht ohne Gewehre zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28686] = { id = 28686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht die freundlichste Stadt", description = "Wart Ihr schon oben auf dem Rostberg, {name}? Ich würde Euch raten, eine frisch geschärfte Klinge mitzunehmen, wenn Ihr dorthin wollt.\n\nDie Leute in dem Dorf sehen vielleicht anständig aus, aber dort geht etwas Seltsames vor sich. Berichten zufolge erledigen sie unsere Soldaten – einen nach dem anderen. Wir haben es langsam satt. Also müsst Ihr für mich dorthin gehen und ein wenig aufräumen.\n\nErledigt so viele Dorfbewohner wie möglich und dann meldet Euch wieder bei mir, wenn Ihr fertig seid.", sourceObjective = "Kommandant Larmash möchte, dass Ihr 14 Bewohner vom Rostberg tötet. Rostberg liegt nördlich des Baradinbasislagers auf der rechten Seite.", completion = "Ich habe doch gesagt, dass das Dorf voller Verrückter ist. Ihr habt beim Aufräumen dort gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28687] = { id = 28687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", description = "Rostberg. Dieser Ort ist für uns ein Fluch und gleichzeitig ein Segen, {name}. Ich habe keine Ahnung, wo die Räuber gelernt haben, so gut zu fischen, aber ich habe jetzt auch keine Zeit, mir darüber den Kopf zu zerbrechen.\n\nIhr müsst dorthin gehen und so viele ihrer Fischreserven wie nur möglich stehlen. Wir leben von Abfällen, seit wir die Insel wieder unter Kontrolle haben und dies ist für uns die beste Gelegenheit, ein paar anständige Lebensmittelvorräte in die Finger zu bekommen.\n\nNehmt Euch dort oben vor Herumschleichern in Acht. Berichten zufolge sind sie innerhalb der Dorfmauern ziemlich verbreitet.", sourceObjective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich in einer Reihe von Ständen an den Docks an der Rückseite des Dorfes. Rostberg liegt nördlich des Basislagers auf der rechten Seite.", progress = "Hattet Ihr Erfolg und habt Ihr uns ein wenig Fisch mitgebracht?", completion = "Diese Fische werden uns trefflich munden, {name}. Die Truppen anständig zu verpflegen und in guter Verfassung zu erhalten hat für uns absoluten Vorrang und Ihr habt Euch sehr für uns eingesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28688] = { id = 28688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Nördliche Schlingendorntal!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Aggro'gosh im Basislager Grom'gol zu melden. Der Kommandant benötigt Eure Hilfe dabei, die Nachschublinien offen und frei von Störungen durch Einheimische und die lästigen Allianzler zu halten.\n\nUm zu Grom'gol zu gelangen, könnt Ihr den Zeppelin an Orgrimmars östlichem Zeppelinturm oder den in der Nähe der Unterstadt nehmen.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[28689] = { id = 28689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen", description = "Viele Soldaten sind schon auf dieser Insel gestorben, {name}. Es ist nur recht und billig, dass wir ihnen unseren Respekt auf jede uns mögliche Art zollen.\n\nIhr müsst für mich zum Vergessenen Hügel reisen, der westlich von hier liegt. Dort müsst Ihr die gequälten Seelen unsere Waffenbrüder erlösen. Aber seid dort drüben wachsam. Es häufen sich Berichte von Aktivitäten der Untoten in diesem Gebiet.", sourceObjective = "Erlöst die Geister von 6 gequälten Seelen am Vergessenen Hügel. Seelen können kanalisiert werden, indem Ihr Eure Hände direkt auf ihre Grabsteine legt. Der Vergessene Hügel liegt westlich von hier jenseits der Rastlosen Front.", completion = "Mögen ihre Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28690] = { id = 28690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", sourceObjective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen bergen, die sich auf dem Vergessenen Hügel herumtreiben. Der Vergessenen Hügel liegt auf der Westseite der Vergessenen Insel hinter der Rastlosen Front.", progress = "Konntet Ihr die verfluchten Oberschenkelknochen bergen? Besser Ihr als ich.", completion = "Ich hätte nicht gedacht, dass Ihr das fertig bringen würdet, {name}. Ihr steckt voller Überraschungen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28691] = { id = 28691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberleutnant Connor", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Flammenschlund. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", sourceObjective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28692] = { id = 28692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinischer Magnetismus", description = "Es fällt einem schwer, auf dieser Insel brauchbare Maschinenteile zu bekommen, {name}. Wir haben versucht, die kaputte Belagerungsmaschine hier im Lager zu reparieren, aber uns gehen immer wieder die Ersatzteile aus.\n\nUnser zweites Regiment meldet ein paar demolierte Belagerungsmaschinen auf einem ehemaligen Schlachtfeld im Westen. Vielleicht findet Ihr dort ein paar Teile?\n\nEs wird nicht leicht sein, auf diesem Schlachtfeld irgendetwas zu finden, also nehmt diesen magnetisierten Schrottsammler mit. Er wird Euch sicherlich von Nutzen sein.", sourceObjective = "Ihr habt die Aufgabe erhalten, 7 Teile Belagerungsmaschinenschrott aufzutreiben. Verwendet den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", progress = "Hat die Magnetapparatur tatsächlich funktioniert?", completion = "Diese Teile helfen uns wirklich weiter, {name}! Wer hätte gedacht, dass man in dem ganzen alten Schrott so viel nützliches Zeug finden würde?", sourceObjectiveStatus = "unverified-source-field" }
quests[28693] = { id = 28693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es zu Ende", description = "Wir versuchen schon die ganze Woche, an der Front brauchbaren Schrott zu sammeln. Jedes Mal, wenn wir eine Ladung zusammengestellt haben und sie zum Lager zurückbringen wollen, werden wir von den rastlosen Soldatan aus der Umgebung angegriffen. Könntet Ihr Euch dorthin begeben und sie beseitigen?", sourceObjective = "Tötet 5 rastlose Soldaten an der Rastlosen Front. Ihr findet die Front auf der westlichen Seite der Insel, direkt vor dem Vergessenen Hügel.", completion = "Wurde auch Zeit, dass sich die Burschen jemand vorknöpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28694] = { id = 28694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Splitter", description = "Wart Ihr schon drüben bei Wellsons Werft, {name}? Man sollte sich unbedingt von dort fernzuhalten. Es sei denn, man hat einen guten Grund, sich dort hineinzuwagen. Unglücklicherweise muss ich Euch genau darum bitten.\n\nSeit wir diese Insel zurückerobert haben, sind wir knapp an Vorräten. Die von Geistern heimgesuchte Werft quillt über vor Nutzholz, aber jedes Mal, wenn wir eine Eskorte dorthin schicken, um das Holz zu holen, kommt sie nicht zurück.\n\nWürdet Ihr uns helfen?", sourceObjective = "Gefreiter Sarlosk hat Euch gebeten, 15 Stück Schiffsbauholz aus Wellsons Werft zu holen. Das Holz kann von den Geistern in der Werft beschafft werden und es liegt auf dem Gelände verstreut herum. Die Werft befindet sich nordwestlich von hier an der Küste.", progress = "Haben die Geister Euch fortgescheucht?", completion = "Ich hätte nicht gedacht, dass Ihr das schaffen würdet, {name}. Ihr steckt voller Überraschungen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28695] = { id = 28695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Wellson", description = "Vorarbeiter Wellson piesackt uns schon, seit wir hierhergekommen sind. In seiner Werft gibt es große Mengen an Vorräten, die für uns extrem nützlich wären... Wenn wir nur zu ihnen gelangen könnten.\n\nEr hat seine Schergen gut im Griff und macht es uns sehr schwer, in der Werft Fuß zu fassen. Diesmal müsst Ihr Wellson für mich endgültig erledigen. Seid vorsichtig, {name}. Wir haben Berichte erhalten, nach denen es in dem Gebiet von dreckigen Allianzlern nur so wimmelt.", sourceObjective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nördlich von hier an der Westküste.", completion = "Hervorragende Arbeit, {name}. Ich werde Euren Einsatz unverzüglich dem Oberbefehlshaber melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28696] = { id = 28696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bom-ben-los!", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", sourceObjective = "Zerstört 10 scheußliche Versorgungsboote.", completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, {name}! Wir wussten, dass Ihr was taugt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28697] = { id = 28697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterjäger", description = "Seht Ihr den Hügel mit den Türmen im Nordosten? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, {name}.", sourceObjective = "Tötet 14 beliebige Geister bei Largos Warte nordöstlich des Hordelagers.", progress = "Wer hat Angst vor Geistern? Ich ganz bestimmt nicht. Na gut, vielleicht im Dunklen.", completion = "Hervorragend, {name}! So bald sollten wir von den Geistern nichts mehr hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28698] = { id = 28698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkugel!", description = "Largo und seine Schergen bedienen sich an unsere Vorräten, seitdem wir hier unser Basislager aufgeschlagen haben. Es ist frustrierend, um es gelinde auszudrücken.\n\nWir haben Berichte erhalten, dass er oben in seiner Warte in den Türmen mit Blick aufs Meer Kanonenkugeln hortet. Könntet Ihr Euch dort hinauf begeben und versuchen, ein paar davon für uns zu beschaffen?\n\n{name}, vergesst nicht, dabei Ausschau nach Allianzlern zu halten.", sourceObjective = "Ihr müsst 4 Haufen Kanonenkugeln aus Largos Warte für den Gefreiten Sarlosk beschaffen. Ihr findet Largos Warte direkt nordöstlich des Basislagers.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Gute Arbeit mit der Beschaffung, {name}. Diese Kanonenkugeln sollten eine Weile reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28699] = { id = 28699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Nördliche Schlingendorntal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Doren im Rebellenlager zu melden.\n\nAuch Jahre nach Colonel Kurzens Verrat gegen Sturmwind bleibt die Wahrheit über das, was geschehen ist, ein Rätsel. Helft den Überlebenden dabei, zu erfahren, was aus dem Colonel geworden ist. Reist vom Dämmerwald aus nach Süden und nachdem Ihr den Dschungel erreicht habt, folgt der Straße nach Westen, um zum Rebellenlager zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", completion = "Willkommen in unserem Lager, {class}, auch wenn wir hier nichts Besonderes für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28700] = { id = 28700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Warte", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, {name}. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", sourceObjective = "Gefreiter Sarslok hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28701] = { id = 28701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sicherheit", description = "Als diese Plage ausgebrochen ist, lagen glücklicherweise keine Druiden im westlichen Grabhügel. Es ist für uns jedoch noch immer eine heilige Stätte und in ihr befinden sich heilige Relikte, die schon seit langer Zeit dort unbehelligt ruhen.\n\nObwohl ich den goblinischen Kammerjägern auf eine Art vertraue, bin ich außerdem... mit den Besonderheiten vertraut, die ihr Volk ausmachen. Bitte bergt aus dem Grabhügel so viele Relikte, wie Ihr finden könnt und bringt sie zu mir zurück, damit sie nicht beschädigt werden. Sie befinden sich in Urnen, die in kleinen Nischen im Hügel aufbewahrt werden.", sourceObjective = "Beschafft 5 Relikte von Sternfall aus den Grabhügeln von Ban'Thallow.", progress = "Ich hoffe, sie waren unversehrt...", completion = "In Euren Augen mögen sie vielleicht nichts Besonderes sein, aber diese Relikte sind für das Volk von Sternfall von unschätzbarem Wert. Ihr seid sehr gütig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28702] = { id = 28702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Schlingendornkap!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga zu melden.\n\nDie Expedition der Forscherliga braucht Eure Hilfe bei der Sicherung der Grabungsstätte und der Bekämpfung der plündernden Oger. Reist vom Nördlichen Schlingendorntal Richtung Süden und folgt der Straße zur Grabungsstätte der Forscherliga.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.", completion = "Es ist gut, dass Ihr hier seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28703] = { id = 28703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinab in den Hügel", description = "Ich habe noch immer keine Ahnung, wo all diese Käfer hergekommen sind. Ich vermute, dass der Kataklysmus ein paar ihrer Nester im Untergrund aufgewühlt hat, von denen wir keine Ahnung hatten, dass sie existierten.\n\nAber es nützt nichts, sich darüber den Kopf zu zerbrechen, da wir sie ohnehin töten!", sourceObjective = "Tötet 10 Krabbler der Kaltlaurer und 5 Wühler der Kaltlaurer.", completion = "Hey, gute Arbeit!\n\nWenn Ihr irgendwann Lust habt, wieder hierher zu kommen und noch ein paar Käfer völlig ohne weitere Belohnung zu töten, tut Euch keinen Zwang an!", sourceObjectiveStatus = "unverified-source-field" }
quests[28704] = { id = 28704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Schlingendornkap!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Sassy Hartzang in Hartzangs Versteck zu melden. Sie benötigt Eure Hilfe mit ein paar Piraten und Naga, die den Dschungel überrannt haben. \n\nReist zu Hartzangs Versteck, indem Ihr vom Nördlichen Schlingendorntal Richtung Süden reist und nach der Stadt südwestlich der Arena der Gurubashi Ausschau haltet.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Sassy Hartzang in Hartzangs Versteck am Schlingendornkap.", sourceObjectiveStatus = "unverified-source-field" }
quests[28705] = { id = 28705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Die Scherbenwelt!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Generalleutnant Orion an den Stufen des Schicksals zu melden.\n\nDort werden Eure Fähigkeiten benötigt, um die Anwesenheit der Brennenden Legion auf den zerschmetterten Resten der Scherbenwelt zu bekämpfen.\n\nBegebt Euch zu Orgrimmars Kluft der Schatten und verwendet das Portal in der Nähe des Magierlehrers, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal selbst, um die Höllenfeuerhalbinsel zu erreichen.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Generalleutnant Orion an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", completion = "Bereitet Euch auf den Kampf vor. Die Horde braucht Euch hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28706] = { id = 28706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "Meine Geschwister sind schon weiter unten im Hügel und versuchen, mit diesen Käfern fertig zu werden, aber sie werden langsam von ihnen überwältigt. Ich sage, es wird Zeit, diese Höhle auszuräuchern.\n\nNehmt diese Räucherapparate. Aber setzt sie nicht selbst ein. Dazu muss man ein gut ausgebildeter Profi sein und das richtige Timing haben. Findet meine Geschwister und verteilt die Geräte an sie.\n\nRemma sollte sich in der Nähe des Eingangs befinden. Begebt Euch den Gang entlang und haltet Euch rechts, sobald Ihr die Rampe hinuntergeht.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Remma Vorhangfeuer im Grabhügel von Ban'Thallow.\n\nBereitgestellter Gegenstand:", completion = "Ihr bringt mir den Käfertod, wie? Ich schätze, dann geht es wohl nicht anders.", sourceObjectiveStatus = "unverified-source-field" }
quests[28707] = { id = 28707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie noch mal aus", description = "Ich werde den hier jetzt vorbereiten.\n\nDer nächste ist für Marcy. Sie ist weiter unten im Hügel. Geht diesen Gang entlang und sucht nach ihr in der nächsten Hauptkammer.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Marcy Vorhangfeuer im Grabhügel von Ban'Thallow.", progress = "Ich habe nicht damit gerechnet, hier unten einen Fremden zu treffen!", completion = "Räucherapparate? Von Rinno? Oje...", sourceObjectiveStatus = "unverified-source-field" }
quests[28708] = { id = 28708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Die Scherbenwelt!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandant Duron auf der Höllenfeuerhalbinsel zu melden.\n\nDie Expeditionskräfte benötigen Eure Unterstützung bei der Bekämpfung der Dämonenarmeen der Brennenden Legion! Verwendet das Portal auf der mittleren Ebene des Turms im Magierviertel, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal, um die Stufen des Schicksals in der Scherbenwelt zu erreichen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Kommandant Duron an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", completion = "Die Expedition braucht Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28709] = { id = 28709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Nordend!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra zu melden.\n\nDie Expedition Valianz benötigt Eure Hilfe dabei, die Kräfte der Geißel unter Kontrolle zu halten und die zivilisierten Länder zu sichern! Begebt Euch zu den Docks von Sturmwind und nehmt das Schiff nach Norden zur Valianzfeste.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra.", completion = "Die Expedition braucht Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28710] = { id = 28710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie schon wieder aus", description = "Rinno hätte uns ruhig mehr Unterstützung schicken können, als nur Euch, {class}! Dieser Schmarotzer...\n\nIch werde den hier jetzt aufstellen. Begebt Euch von diesem Raum aus nach Norden durch den Gang und sucht nach Sana. Sie hat sich vermutlich in der letzten Kammer verirrt. Also seht auch in den Seitengängen nach, sobald Ihr dort eintrefft.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Sana Vorhangfeuer im Grabhügel von Ban'Thallow.", progress = "Was macht Ihr hier?", completion = "Rinno hat Euch geschickt? Und ihr habt... Räucherapparate dabei? Pfui!", sourceObjectiveStatus = "unverified-source-field" }
quests[28711] = { id = 28711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nordend!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste zu melden.\n\nDie Kriegshymnenoffensive benötigt Eure Hilfe dabei, die anhaltende Bedrohung durch die Untoten der Geißel zu beenden.\n\nNehmt den Zeppelin an Orgrimmars westlichem Zeppelinturm zur Kriegshymnenfeste und stellt Euch beim Rekrutierungsoffizier vor.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste in der Boreanischen Tundra.", completion = "Die Kriegshymnenoffensive könnte mehr von Eurer Sorte gebrauchen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28712] = { id = 28712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt der Drachenkönigin", description = "Hallo, {race}. Ich wünschte, unser Treffen würde unter erfreulicheren Umständen stattfinden. Die Welt hängt an einem seidenen Faden und alles, was die Titanen erschaffen haben, steht auf dem Spiel.\n\nEs betrübt mich zutiefst, aber mein Urteil ist unumstößlich. Todesschwinge, die entsetzliche Kreatur, die einst der Erdenwächter und mein Freund war, muss vernichtet werden.\n\nIch habe eine Stätte oben im Hochland errichtet. Sie liegt westlich des Zinnoberrefugiums. Dort kann ich es zu Ende bringen. Sucht nach dem Kreis des Lebens. Darin befindet sich Lirastrasza. Sprecht mit ihr. Ich werde dort zu Euch stoßen.", sourceObjective = "Sprecht mit Lirastrasza im Kreis des Lebens im Schattenhochland.", completion = "Hallo, {race}. Ich habe gehört, dass Ihr bei unserem Vorstoß gegen Grim Batol von großer Hilfe wart. Habt Dank!\n\nAlexstrasza hat diesen Boden geheiligt, in der Hoffnung damit Todesschwinge hierher zu locken. Sie wird eine Zeremonie durchführen, um ihn hervorzulocken und ihn dann in diesem heiligen Kreis zu vernichten.\n\nHoffen wir, dass ihr Plan aufgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28713] = { id = 28713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht der Natur", description = "Seid gegrüßt, {name}. Ich bin Ilthalaine. Meine Aufgabe im Laubschattental besteht darin, junge Helden wie Euch auszubilden, {class}, und sicherzustellen, dass das Naturgleichgewicht erhalten bleibt.\n\nDer Frühlingsregen war dieses Jahr besonders reichlich. Einige Geschöpfe des Dschungels haben davon profitiert und andere haben darunter gelitten. Unglücklicherweise ist die Zahl der Nachtsäbler zu groß geworden und sie werden andere Kreaturen ausrotten, wenn sie nicht selbst dezimiert werden.\n\nReist weiter, {class}, und dünnt die Population der Nachtsäbler aus, damit die Harmonie der Natur erhalten bleibt.", sourceObjective = "Tötet 6 junge Nachtsäbler.", completion = "Ihr seid Eurer Pflicht vorbildlich nachgekommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28714] = { id = 28714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbtes Teufelsmoos", description = "Ihr scheint zu wissen, was Ihr tut. Vielleicht kann ich Euch mit einer etwas gewichtigeren Aufgabe betrauen.\n\nWie Ihr vielleicht wisst, wurde die Verderbnis in Teldrassil angeblich ausgemerzt. Und doch geht etwas Verdorbenes um. Die Kreaturen haben sich nicht beruhigt und es plagen uns weiter alle möglichen Probleme.\n\nIhr müsst Euch um die Grellkin kümmern, die sich im Westen versammelt haben und während Ihr dort seid, möchte ich, dass Ihr sie nach Teufelsmoos absucht. Dies wird mir helfen, herauszufinden, woher diese fortgesetzte Verderbnis stammt.", sourceObjective = "Sammelt 6 Teufelsmoose von den Grellkin im Westen von Ilthalaine.", progress = "Bestätigt meinen Verdacht, {name}. Bringt mir das Teufelsmoos von den Grellkin.", completion = "Für Euren Dienst an den Geschöpfen des Laubschattentals habt Ihr Euch eine Belohnung verdient, {name}.\n\nMeine Sorge habt Ihr jedoch bestätigt. Die Grells sind trotz der Segnung Teldrassils noch immer vom Teufelsmoos befleckt. Etwas Finsteres ist in dem Baum verblieben. Ich kann nur hoffen, dass der Furbolgstamm der Knarzklauen frei von Verderbnis ist, oder wir sind noch immer in großer Gefahr.\n\nIch werde mich näher damit befassen und mich mit denjenigen in Verbindung setzen, die uns helfen können. Habt Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28715] = { id = 28715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Diebe", description = "Bösartige kleine Grells! Sie haben schon wieder etwas von unseren Lebensmittelvorräten gestohlen.\n\nWenn es Euch nichts ausmacht, mir zur Hand zu gehen: Sie haben sicherlich meine gestohlenen Taschen in ihrem Lager im Westen. Ich werde Euch mit Freuden belohnen, wenn ihr sie mir zurückbringt.", sourceObjective = "Beschafft Melithars gestohlene Taschen in der Nähe der Grellkin im Westen.", progress = "Ich habe keine Vorräte für meine Kunden, bis meine gestohlenen Waren wieder bei mir sind. Wie ist es gelaufen?", completion = "Elune sei gepriesen! Und Ihr ebenfalls, {class}.\n\nViele junge Nachtelfen benötigen diese dringend, aber es ist mir eine große Freude, Euch eine dieser Taschen als Belohnung zu überreichen. Ich bin mir sicher, sie wird Euch von Nutzen sein.\n\nIch wünsche Euch eine sichere Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[28716] = { id = 28716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Schattenhochland!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend im Thronraum von Burg Sturmwind einzufinden.\n\nKönig Wrynn benötigt einen vertrauenswürdigen und erfahrenen Helden für eine Aufgabe von höchster Wichtigkeit.\n\nBurg Sturmwind befindet sich im östlichen Teil von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Sprecht mit König Varian Wrynn in Burg Sturmwind in Sturmwind.", completion = "Wir sind erfreut, dass Ihr unserem Ruf gefolgt seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28717] = { id = 28717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Schattenhochland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Garrosh Höllschrei in der Feste Grommash zu melden.\n\nDer Kriegshäuptling braucht Eure Hilfe bei der Vorbereitung eines glorreichen Angriffs auf das Schattenhochland und unsere beiden Feinde: die Allianz und den Schattenhammer.\n\nTrefft den Kriegshäuptling in der Feste Grommash, die mitten in Orgrimmars Tal der Stärke liegt.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Garrosh Höllschrei in der Feste Grommash in Orgrimmar.", completion = "Bald wird der Angriff auf das Schattenhochland beginnen und ich will, dass Ihr daran teilnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28718] = { id = 28718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo es Rauch gibt, ist auch köstliches Fleisch", description = "Heda, {class}... Mögt Ihr Fleisch? Oder besser: mögt Ihr Geld? \n\nEiner meiner Cousins zweiten Grades verdient sich eine goldene Nase mit Tiefkühlfleisch. Er hat eine Räuchergrube oben im Norden eingerichtet und er braucht Hilfe bei der Jagd auf all die gefährlichen Bestien, die gewöhnlich so vorzüglich schmecken.\n\nFleischfresser zahlen gut. Ich bin hier zu sehr in diesem Grabhügel beschäftigt. Was habe ich mir nur dabei gedacht? Ich kann also den Tipp genauso gut an jemanden wie Euch weitergeben, {race}.\n\nSein Name ist Jez. Begebt Euch nach Nordosten und haltet einfach Ausschau nach dem Rauch!", sourceObjective = "Findet Jez Gutmampf in Gutmampfs Räuchergrube in Winterquell.", completion = "Seht Euch um. Das ist das größte Jagdreservat in ganz Kalimdor, das in der Hand von Goblins ist! Ich habe eine Abschusslizenz und esse alle Kreaturen, die sich zwischen hier und der Ewigen Warte auf dem Schnee bewegen... Und eins kann ich Euch sagen: Sie schmecken prima!", sourceObjectiveStatus = "unverified-source-field" }
quests[28719] = { id = 28719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig gewöhnungsbedürftig", description = "Viele finden das Fleisch des Splitterzahnbären etwas zu gewöhnungsbedürftig. Ich bin anderer Meinung, obwohl es mir nicht zusteht, den Geschmack von anderen zu verurteilen.\n\nDie Splitterzahnraufer jedoch – ihre braunfelligen Cousins im Süden – haben ein sehr viel zarteres Fleisch, besonders an ihren Tatzen. Ich habe gehört, dass die Schnauze ebenfalls als Delikatesse gilt.\n\nSetzt Eure Jagd fort, {name}. Zeigt mal, ob Ihr diese Splitterzahnraufer für den ollen Francis in den Sack stecken könnt.", sourceObjective = "Tötet 15 Splitterzahnraufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28722] = { id = 28722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetiphobie", description = "Es ist alles bereit, {name}!\n\nJetzt habe ich meiner Freundin Legacki erzählt, dass ich eine Überraschung für sie habe. Und da kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Euch gebührt die Ehre, sie damit zu überraschen. Ihr findet sie auf der anderen Seite der Ewigen Warte in der Nähe des Gasthauses.\n\nBegebt Euch zu Ihr und schaltet den Yeti ein... Ich werde von hier aus zusehen!", sourceObjective = "Erschreckt Legacki mit Umis mechanischem Yeti.", progress = "Damit wird sie niemals rechnen!", completion = "Ha! Sie wird es sich zweimal überlegen, bevor sie sich wieder über meine Ideen lustig macht!\n\nHabt Dank für Eure Hilfe, {name}. Ohne Euch hätte ich nie so viel Spaß gehabt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28723] = { id = 28723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondpriesterin", description = "Jetzt, wo Ihr Euch in Eurer neuen Fähigkeit geübt habt, seid Ihr vielleicht bereit uns beim Kampf gegen die Verderbnis zu helfen, die das Laubschattentals heimsucht.\n\nMondpriesterin Dentaria Silbertal hat uns ihre Hilfe angeboten. Ihr solltet sie zwischen den beiden Teichen nördlich unseres Großen Baumes finden. Schlagt einen Bogen um den Baum, um zu ihr zu gelangen und helft ihr so gut Ihr könnt, {class}.", sourceObjective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im Zentrum des Laubschattentals.", completion = "Es ist gut, dass Ihr gekommen seid. Es scheint, Eure Ausbildung schreitet schnell voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28724] = { id = 28724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Unser Freund Iverron ist vom Gift der Waldweberspinne befallen worden. Ich kann dafür sorgen, dass sich sein Zustand nicht verschlechtert, aber ich brauche jemanden, der eine Zutat sammelt, damit ich ihm ein Gegengift mischen kann.\n\nÜberall um die Teiche herum solltet Ihr Mondblütenlilien finden. Diesen Blumen wohnt eine große Heilkraft inne. Wenn ich sie gemeinsam mit anderen Zutaten verwende, die ich bereits habe, kann ich Iverron wieder gesund machen.\n\nWürdet Ihr sie für mich sammeln? Es müsste viele in Sichtweite von hier in der Nähe des Ufers geben.", sourceObjective = "Sammelt 7 Mondblütenlilien.", progress = "Unserem lieben Freund geht es nicht sehr gut - trotz meiner Pflege. Habt Ihr mir gebracht, was ich benötige?", completion = "Die sind perfekt. Habt Dank, {name}. Besonders für Eure Schnelligkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28725] = { id = 28725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützerin des Waldlandes", description = "Nun muss ich Euch um einen Gefallen bitten, der durchaus gefährlich ist. Seltsame Kunde ist mir durch das Tuscheln der Waldgeister zu Ohren gekommen. Die rätselhafte Beschützerin des Waldlandes, Tarindrella, ist ins Laubschattental zurückgekehrt.\n\nDie Anwesenheit der Dryade war das letzte Mal vor der Segnung von Teldrassil zu spüren. Irgendetwas muss im Argen liegen, wenn sie zurück in dieses Land gereist ist.\n\nSucht nach Tarindrella in der Schattenweberhöhle im Norden. Es ist gefährlich, aber wir werden dieses Gegengift sicherheitshalber bereithalten.", sourceObjective = "Sucht nach der Dryade mit dem Namen Tarindrella in der Schattenweberhöhle am nördlichen Ende des Laubschattentals.", completion = "Ich sehe, Ihr habt mich gefunden, {race}. Dentaria war weise genug, Euch zu mir zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28726] = { id = 28726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis der Waldweber", description = "Ich hatte gehofft, niemals wieder wegen solch düsterer Angelegenheiten nach Teldrassil zurückzukehren. Ich hoffte, dass hier die Verderbnis inzwischen vollständig ausgerottet sei. Etwas Schändliches geht um.\n\nDiese Spinnen leiden viel stärker unter der Verderbnis als die anderen Tiere der Umgebung. Sie werden zu einer Gefahr für mein Volk und zu einer Gefahr für den Wald. Wir müssen Ihre Anzahl dezimieren, aber noch wichtiger: Wir müssen die Quelle der Verderbnis finden, die sie plagt.\n\nIch werde mit Euch kommen und Euch in dieser Sache unterstützen.", sourceObjective = "Tötet 12 Waldweberspinnen.", progress = "Dies ist eine abscheuliche Arbeit. Es schmerzt mich, dass wir so viel Gewalt über ein Geschöpf des Waldes bringen müssen, sei es nun verdorben oder nicht.", completion = "Die Verderbnis, unter der diese Spinnen zu leiden haben, ist nicht nur oberflächlich. Es kann weder Magie sein noch unterschwellige Böswilligkeit. Es ist in sie hineingezüchtet worden.\n\nEs ist offensichtlich, was unsere nächste Aufgabe ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28727] = { id = 28727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheuliche Berührung", description = "Wenn diese Spinnen alle schon mit der Verderbnis in ihren Adern geboren wurden, dann muss ihre Brutmutter die Quelle dieses Bösen sein.\n\nBrechen wir auf in den äußersten nördlichen Winkel dieser Höhle und suchen wir Githyiss die Üble. Sie trägt die Antwort, die wir suchen, in sich.", sourceObjective = "Tötet Githyiss die Üble am Nordende der Schattenweberhöhle.", progress = "Ich verehre diese Wälder. Ich will, dass sie vollständig von dieser Verderbnis befreit werden. Wenn ich das nächste Mal zurückkehre, will ich es froheren Herzens tun.", completion = "Githyiss und ihre Brut wurden von diesem Totem verdorben. Dies ist ein Totem der Furbolgs.\n\nDies ist tatsächlich sehr beunruhigend. Es bedeutet, dass die Knarzklauen noch immer eine Gefahr für diesen Wald darstellen. Wir haben uns zu früh zu sicher gefühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28728] = { id = 28728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anzeichen der Dinge, die da kommen werden", description = "Ich werde der Spur der Knarzklauen nachgehen und dieser Verderbnis bis zu ihrer Quelle folgen. Falls Ihr jemals Athridas Bärenfell in Dolanaar begegnet: Er weiß über die Probleme dieses Waldes genauestens Bescheid und er kann Euch raten, wie Ihr weiter helfen könnt. \n\nIch bin mir sicher, dass wir uns wiedersehen. Vielleicht könntet Ihr mir dabei helfen, die Quelle dieser Verderbnis zum Versiegen zu bringen, sobald wir sie ausgemacht haben. Jetzt werde ich Euch zurück zu Dentaria bringen, sodass Ihr Eure Ausbildung abschließen könnt. Habt Dank für alles, was Ihr für uns getan habt, {name}.", sourceObjective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im nördlichen Laubschattental.", completion = "Ihr seid zurückgekehrt! Es ist gut, dass Ihr hier seid. Es scheint, Ihr habt die Quelle der Verderbnis erfolgreich bekämpft, die große Teile des Laubschattentals bedroht hat.\n\nTeldrassil leidet noch immer und bedarf weiterhin unserer Aufmerksamkeit, aber wir können einen Augenblick dafür aufwenden, Eure Ausbildung hier im Laubschattental abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28729] = { id = 28729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Krone von Azeroth", description = "Als Teil des Abschlussrituals Eurer Ausbildung hier im Laubschattental werdet Ihr etwas über unsere jüngere Geschichte erfahren.\n\nDafür müsst Ihr eine Aufgabe erfüllen. Geht zum Mondbrunnen im Nordosten und füllt eine Phiole mit seinem Wasser. Während Ihr dort seid, werdet Ihr einen flüchtigen Augenblick unserer Magie zu Gesicht bekommen und etwas über unsere Vergangenheit erfahren.\n\nWenn Ihr dort fertig seid, bringt das Wasser zu mir zurück und ich werde Euch weitere Anweisungen geben.", sourceObjective = "Füllt die Kristallphiole am Mondbrunnen im nordöstlichen Laubschattental.", progress = "Unsere jüngere Geschichte ist voller Zwietracht und Gewalt. Es gibt noch immer viel, womit wir uns arrangieren müssen.", completion = "Gut gemacht, {name}. Ihr habt noch eine Aufgabe vor Euch, bevor Ihr vom Laubschattental zur offenen Wildnis von Teldrassil reist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28730] = { id = 28730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Wasser", description = "Tenaron Sturmgewalt überwacht alles, was in diesem Tal geschieht. Er hat seinen Wohnsitz auf der Spitze Aldrassils.\n\nFalls Ihr nach Süden blickt, werdet Ihr den unteren Teil der Rampe sehen, die zu ihm hinaufführt. Steigt diese Rampe hinauf und vollendet Eure Ausbildung.\n\nEs war wundervoll, Euch kennengelernt zu haben, {name}. Ich bin sehr stolz, zu wissen, dass unter den jungen Nachtelfen auch solche sind, die so selbstlos und voller Leben sind wie Ihr. Ihr werdet große Taten für unser Volk vollbringen. Ihr werdet große Dinge in dieser Welt tun.\n\nMögen wir uns bald wiedersehen.", sourceObjective = "Bringt die gefüllte Kristallphiole zu Tenaron Sturmgewalt auf der Spitze von Aldrassil im Laubschattental.", progress = "Die Mondbrunnen enthalten die Wasser des Brunnens der Ewigkeit, der uralten Quelle der Magie, die so viele Schrecken über unsere Welt gebracht hat.\n\nDie Druiden nutzen die Eigenschaften des Wassers, die Schildwachen verehren die Brunnen als Schreine der Elune und jetzt richten sogar die zurückgekehrten Hochgeborenen sehnsüchtige Blicke auf die Brunnen.", completion = "Ihr habt also den ersten Teil der Nachwirkungen von der Schlacht am Hyjal erfahren. Es gibt noch viel mehr für Euch zu erfahren und die Aufgabe, die Ihr hier begonnen habt, wird sich für den Rest Eurer Reise durch Teldrassil bis nach Darnassus fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28731] = { id = 28731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Gebt das Wissen weiter", description = "Es gibt noch mehr, was ich Euch über die Mondbrunnen erzählen könnte und über Teldrassil, aber ich muss Euch nun fortschicken. Corithras Mondzorn wird Euch erwarten. Ich habe die Phiole mit dem Wasser, das Ihr gebracht habt, in dieses Gefäß gefüllt.\n\nSucht nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil aus dem Laubschattental hinaus und geht weiter entlang der Pflastersteine, wenn sich die Straße nach Westen wendet.\n\nAchtet aber darauf, auf der Straße zu bleiben, {name}. In den Wäldern lauern neuerdings gefährliche Ungeheuer.", sourceObjective = "Bringt das teilweise gefüllte Gefäß zu Corithras Mondzorn in Dolanaar.", progress = "Seid gegrüßt, {class}. Welchem Anlass verdanke ich die Freude unserer Zusammenkunft?", completion = "Ah, ich verstehe. Tenaron hat Euch gesandt. Nun gut, es scheint, dass wir viel zu bereden und noch mehr zu tun haben.\n\nBevor wir uns um die zu erledigende Aufgabe kümmern, solltet Ihr die Lektion dieses Mondbrunnens erlernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28732] = { id = 28732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das kann nur eins bedeuten...", description = "Raz und ich wurden von den Wächtern des Hyjal beauftragt, das Wiederauftauchen von Ragnaros in unsere Welt zu untersuchen. Lasst mich weiterziehen und bestätigen, dass er zurück ist und dass er erzürnt ist! Wir haben außerdem Beweise, dass diese Schattenhammerkultisten Elementare von hier zu den Schwarzfelshöhlen in den Östlichen Königreich bringen.\n\nRaz und ich waren auf dem Weg dorthin, um die Sache zu untersuchen. Wir haben in der Maulwurfmaschine noch Platz für eine Person, falls Ihr interessiert seid? Trefft uns einfach draußen und unsere Reise kann beginnen.", sourceObjective = "Nehmt Pips Maulwurfmaschine zum Schwarzfels.", progress = "HILFE! HILFE!", completion = "Oje, Raz wurde gefangengenommen! Sobald wir drin waren, haben uns ein dutzend Schattenhammerkultisten und ein dicker, fetter Oger angegriffen. Ich bin losgerannt, während Raz versucht hat, sie abzuwehren. Wir müssen ihn retten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28733] = { id = 28733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzenkunde für Anfänger", description = "HILFE! HILFE! Durchgedrehte Untote greifen meinen Hof an! Dieser verrückte Aufseher drüben bei den Schlickfeldern ist vermutlich für diese Sauerei verantwortlich. Helft mir, die Zombies abzuwehren!", sourceObjective = "Überlebt eine riesige Zombiewelle.", completion = "PUH! Das war knapp! Ihr seid ein echtes Naturtalent, wenn es um diese Pflanzen geht, {class}. Wisst Ihr, ich habe die Samen hier von den Verlorenen Inseln mitgebracht. Ich bin mir sicher, sobald ich alles über sie herausgefunden habe, werde ich ein Vermögen mit dem Verkauf von tödlichen Blumen machen!\n\nWa... SEHT! ES KOMMEN NOCH MEHR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28734] = { id = 28734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für Melithar", description = "Ihr solltet mit Melithar sprechen. Ich glaube, er hatte bereits einige Probleme mit den Grells.\n\nIch schätze, er kann Euch Platz anbieten, an dem Ihr einiges von Eurem Hab und Gut verstauen könnt, falls Ihr ihm helft.", sourceObjective = "Sprecht mit Melithar Hirschhaupt im Laubschattental.", completion = "Ilthalaine hat Euch geschickt? Es war weise von ihm, das zu tun. Ich brauche in der Tat Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28735] = { id = 28735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Kammer der Einäscherung!", description = "Es war ein Hinterhalt, {name}! Kaum waren wir drin, griff uns ein dicker, fetter Oger namens Rom'ogg Knochenbrecher an! Raz hat mich mutig verteidigt, während ich davongerannt bin, um mich zu verstecken. Ich musste zusehen, wie sie ihn bewusstlos schlugen und ihn dann zu einem Ort brachten, den der Fette \"Kammer der Einäscherung\" nannte. Ich glaube, sie ist in der Halle auf der anderen Seite der Brücke.\n\nIch habe zu viel Angst, um auch nur einen Schritt weiter zu gehen. Nehmt meinen Allzwecktaucherhelm und sucht nach Raz. Durch den Helm kann ich mit Euch sprechen.\n\nUnd wenn Ihr diesen Oger findet, tötet ihn!", sourceObjective = "Tötet Rom'ogg Knochenbrecher.", completion = "<Finkles Helm knistert vor statischer Aufladung.>\n\nRAZ! Was haben sie ihm angetan!? FOLGT IHM!", sourceObjectiveStatus = "unverified-source-field" }
quests[28736] = { id = 28736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer vom Himmel", description = "Die Überreste von Schnottz' Organisation halten sich hier beharrlich auf dem Aufstieg des Schöpfers, was dieses Gebiet für jeden, der sich nähert, zur Todesfalle macht.\n\nEs gibt reichlich Munition, aber ohne einen guten Beobachter schieße ich einfach blindwütig umher.\n\nSpringt auf und geht mir zur Hand. Diesen Soldaten wird das Hören und Sehen vergehen!", sourceObjective = "Steigt in die beschlagnahmte Artillerie und verwendet sie, um 100 Infanteristen von Schnottz zu töten.", progress = "Hier gibt es reichlich Ziele, {class}.", completion = "Der Feind auf dem Aufstieg des Schöpfers bleibt eine Bedrohung, aber dank Eurer Hilfe haben wir ihrer Anzahl und ihrem Kampfgeist einen ernsthaften Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28737] = { id = 28737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Pips Helm versetzt Euch einen leichten Stromschlag.>\n\nWas ist das für ein Ort? Es sieht aus, als würden sie dem Netherdrachen schreckliche Dinge antun. Seine Energie wird in die Frau dort geleitet! Wir müssen das Ritual aufhalten!\n\nTötet Corla, um diese Halle hinter Euch zu lassen!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nUns bleibt nicht viel Zeit. Sieht aus, als wäre Raz verletzt. Wenn wir ihn rechtzeitig erreichen, haben wir vielleicht sogar eine Chance, ihn in einen gewöhnlichen Orc zurückzuverwandeln!\n\n<Ihr fühlt einen stechenden Schmerz im Hinterkopf und hört das Klingeln von Münzen>\n\nEntschuldigt das. Ich dachte, ich würde Euch etwas Gold durchschicken... für Eure Mühen und so...", sourceObjectiveStatus = "unverified-source-field" }
quests[28738] = { id = 28738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwielichtschmiede", description = "<Pips Helm summt vor Energie.>\n\nVerdammt nochmal! Raz hört einfach nicht auf! Es ist, als hätte ihn eine brennende Rachsucht gegen alles mit Zwielicht im Namen ergriffen! Sieht so aus, als müssten wir den Zwielichtrüstungsschmied Karsh Stahlbieger ausschalten, wenn wir den Raum hinter uns lassen und zu Raz aufschließen wollen.", sourceObjective = "Tötet Karsh Stahlbieger.", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nDas sollte ihrem Arsenal ein Ende bereitet haben... zumindest vorerst.\n\nRaz ist über die Rampe auf der anderen Seite der Schmiede weggerannt. LOS, LOS, LOS!", sourceObjectiveStatus = "unverified-source-field" }
quests[28740] = { id = 28740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich meinen Augen trauen?", description = "<Ein lautes, mädchenhaftes Kreischen entweicht Pips Helm.>\n\nDAS KANN NICHT SEIN! Ich... Ich habe fast einen ganzen Monat in einem dieser Dinger festgesteckt. Ja, buchstäblich im Magen. Ohne meinen Anzug und meinen Allzwecktaucherhelm hätte mich ein feuriger Tod ereilt! Und schaut Euch das an, es hat Nachwuchs bekommen!\n\nI... Ihr müsst dieses Ding aufhalten, {name}! Wir dürfen nicht zulassen, dass es oder sein Nachwuchs hier lebendig hier rauskommen!", sourceObjective = "Tötet Bella", progress = "<Finkles Helm knistert vor statischer Aufladung.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nPuh... Eine Sache weniger, um die ich mir Sorgen machen muss, sollten wir es hier jemals rausschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28741] = { id = 28741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aszendentenfürst Obsidius", description = "<Pips Helm brummt.>\n\nMEINE GÜTE! Schaut Euch diesen Ort an! S... Sind das etwa Kratzspuren von Todesschwinge an der Decke?! Und was ist das für eine Kreatur da in der Mitte der Kammer?\n\nIch kann Raz nicht sehen. Kümmern wir uns um dieses Monster und finden Raz!", sourceObjective = "Tötet Aszendentenfürst Obsidius.", completion = "Armer Raz. Er war der beste Freund, den ein Gnom jemals hatte. Zumindest haben wir seinen Tod gerächt und diese höllischen Höhlen gesäubert!", sourceObjectiveStatus = "unverified-source-field" }
quests[28742] = { id = 28742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Zeit für den großen Abschuss, Kumpel! Shy-Rotam schleicht im Norden umher - der größte Frostsäbler, den es gibt.\n\nIhr solltet Euch geehrt fühlen. Es gibt keine größere Herausforderung für einen Jäger... und wenn Ihr die Belohnung gesehen hättet, die mir von diversen Leckermäulern angeboten wurde, die ein Stück von diesem Kerl haben wollen, würden Euch die Augen ausfallen!\n\nSobald Ihr ihn erledigt habt, kommt zurück zum Lager. Ihr wollt unsere Frostsäblerpopulation schließlich nicht an einem Tag ausrotten...", sourceObjective = "Tötet Shy-Rotam.", completion = "Erstaunlich. Ihr seid einen Tick besser als die anderen! Ich bin habe ungefähr fünf verschiedene Vertragsjäger angeheuert, um diese Katze zu töten.\n\nNun, zwei von ihnen haben wir gefunden, nachdem der Hauptmann den Kadaver bekommen hatte, aber vertiefen wir das nicht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[28743] = { id = 28743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heckschütze!", description = "Ist Euch nach ein wenig Jagen zumute, {name}?\n\nSteigt ein! Ich fliege, Ihr schießt!", sourceObjective = "Schießt 15 Fliegerasse von Schnottz ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28744] = { id = 28744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghule hassen meine Saat", description = "Ihr seid ein Fachmann in dieser Sache, {name}! Ein regelrechter Aushilfsbotaniker! Hört, ich habe ein neues Saatgut auszutesten, das Felsnuss genannt wird. Verwendet es, um die Untoten zu blockieren. Werft es einfach auf den Boden und sie bleiben wie angewurzelt stehen. Untote sind so dämlich!\n\nVersuchen wir es!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", completion = "Ich glaube, ich habe Stillwasser erzürnt. Jetzt fährt er die großen Geschütze auf. Keine Zeit zu verlieren, los geht's!", sourceObjectiveStatus = "unverified-source-field" }
quests[28745] = { id = 28745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmackhafte Kreischer", description = "Diese kleineren Eulen sind schon sehr lecker, aber Gutmampf sagt, es gibt weiter im Süden sogar noch größere! \"Kreischer\" werden sie von den Leuten aus der Gegend genannt. Sie machen ganz schön viel Lärm, wenn man sich mit ihnen prügelt. \n\nAber er sagt, es sind die besten Eulen, die er je gekostet oder verkauft hat und ich glaube ihm. Warum scheucht Ihr nicht ein paar von ihnen für uns auf und ich streite mich hier weiter mit Francis.", sourceObjective = "Tötet 15 Winterquellkreischer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28746] = { id = 28746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Verteidigung durchbrechen", description = "Los geht's, {name}!\n\nDirekt hinter dieser Tür liegt der Kontrollraum.\n\nIch renne einfach hinein, deaktiviere den Neuerschaffungsmechanismus und dann gehen wir alle wieder nach Hause. So einfach ist das.\n\nIhr werdet sehen, <Bursche/Mädel>, es ist diese hohe Kunst der Vorbereitung, die den wahren Archäologen von dem durchschnittlichen Jäger eines verlorenen Schatzes unterscheidet.\n\nEs ergibt keinen Sinn, die Bestien aufzumischen, wenn man's nicht muss. Man veranstaltet nur unnötig ein großes Durcheinander...", sourceObjective = "Verschafft Euch Zutritt zum Kontrollraum der Titanen.", progress = "Was gibt's, {name}?", completion = "Nun, ich habe eine schlechte Nachricht für Euch und eine...\n\nNein, streicht das. Ich habe nur schlechte Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28747] = { id = 28747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbisbomben", description = "Habt Ihr so was schon mal gesehen?\n\n<Brazie zieht einen Kürbis heraus.>\n\nDies sind keine gewöhnlichen Kürbisse. Seht, sobald man sie einpflanzt, warten sie bis ein Zombie auftaucht und dann, KABUMM, fliegen die Zombies in Einzelteilen durch die Luft. Los geht's!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", completion = "H... Habt Ihr das Rumpeln gehört? Ich glaube, Stillwasser kommt! Heiliger Strohsack, passt auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[28748] = { id = 28748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasen der lebenden Toten", description = "ES IST STILLWASSER! ER IST FAST HIER! Wir werden alles ins Rennen werfen müssen, was wir haben, um ihn zu schlagen. Auf geht's!", sourceObjective = "Besiegt Aufseher Stillwasser.", completion = "Ich kann nicht glauben, dass wir ihn besiegt haben, {name}! Das war der härteste Kampf, den wir bisher hatten, aber es gibt noch immer Hunderte von durchgeknallten Zombies, die im Hügelland ihr Unwesen treiben. Wir müssen auf der Hut bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28749] = { id = 28749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Gerade ist ein Greif mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. König Wrynn hat eine Entscheidung getroffen und einen Todesritter geschickt, der seine Sache anführen soll, aber ich bin mir sicher, dass er jede Hilfe braucht, die er bekommen kann. \n\nDie Nachricht sagt ausdrücklich: \"{class} von der Allianz für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", sourceObjective = "Sprecht mit Kriegsmagier Erallier, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Thassarian in Andorhal.", completion = "Es wurde Zeit, dass Ihr kommt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28750] = { id = 28750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Gerade ist ein Windreiter mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal ist in der Mitte eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. Es klingt so, als ob Sylvana eine Entscheidung getroffen hat und um es noch interessanter zu machen, hat sie dem Todesritter Koltira Todesweber das Kommando übertragen.\n\nDie Nachricht sagt ausdrücklich: \"{class} von der Horde für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", sourceObjective = "Sprecht mit Arkanist Arman, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Koltira Todesweber in Andorhal.", completion = "Es wurde Zeit, dass Ihr kommt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28751] = { id = 28751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut jäten", description = "Obwohl wir Aufseher Stillwasser geschlagen haben, streifen seine Zombies noch immer durch die Gegend. Seht dort, eine neue Welle nähert sich uns! Helft mir, sie zurückzuschlagen, Kumpel! Los geht's!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28752] = { id = 28752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsamer Ansturm", description = "Seht, wie lange Ihr durchhaltet! Übersteht mindestens 10 Anstürme und ich gebe Euch ein paar Münzen." }
quests[28753] = { id = 28753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die harte Tour", sourceObjective = "Brann Bronzebart will, dass Ihr Isiset, Ammunae, Setesh und Rajh tötet.", completion = "Aaalso gut.\n\nDeponieren wir diese Scheiben und das war's dann!", sourceObjectiveStatus = "unverified-source-field" }
quests[28755] = { id = 28755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annalen der Silbernen Hand", description = "Wisst Ihr, wer die Ritter der Silbernen Hand waren? Es waren die ursprünglichen Paladine des Lichts und aus ihren Reihen stammten die Ritter, die später der Argentumdämmerung oder den Scharlachroten Kreuzfahrern beitraten. Obwohl viele vom Weg abgekommen sind, besitzen sie noch immer wertvolle Relikte der Silbernen Hand.\n\nTief in Stratholme unter den wachsamen Augen von Archivar Galford haben Bände der Annalen der Silbernen Hand die Zeiten überdauert. Jeder Band, den Ihr auftreiben könnt, wäre eine passende Ergänzung für die umgewidmete Kapelle des Hoffnungsvollen Lichts.", sourceObjective = "Treibt einen verschollenen Band der Annalen der Silbernen Hand in Stratholme auf.", progress = "Konntet Ihr die verschollenen Aufzeichnungen der Silbernen Hand ausfindig machen?", completion = "Dies ist tatsächlich einer der verschollenen Bände! Tyrosus wird hocherfreut sein, wenn er von Eurem Fund erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28756] = { id = 28756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entartung des Knochens", description = "Im Leben kämpften meine Brüder und ich gegen all die Kräfte der Geißel, aber niemand war so schändlich wie die Totenbeschwörer. Es hat ihnen nicht gereicht, unsere toten Kameraden auferstehen zu lassen und sie gegen uns kämpfen zu lassen, nein, sie erschufen perverse Golems aus Knochen mit Sicheln statt Händen.\n\nDiese Entartungen töteten viele meiner Brüder und dennoch konnten sie nicht alle vernichten. Ich bitte Euch, {name}, die Aufgabe der Gefallenen fortzuführen. Reist in das Ossuarium von Scholomance und vernichtet die größte und gefährlichste dieser scheußlichen Kreaturen.", sourceObjective = "Tötet Blutrippe im Ossuarium von Scholomance.", completion = "Eure Taten ehren diejenigen, die bei der Verteidigung dieses heiligen Bodens gefallen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28757] = { id = 28757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28758] = { id = 28758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um Leben und Tod", description = "Todesschwinge und Alexstrasza haben sich in den Himmel über Grim Batol erhoben! Ihr Plan droht zu scheitern - die Königin der Drachen ist außerhalb des Kreises des Lebens, den sie zuvor eingerichtet hat. Wir werden sie mit allem unterstützen müssen, was wir haben.\n\nBeeilung! Steigt auf einen der Zinnoberroten Vorposten hinter mir.\n\nWenn wir auf irgendwelche Zwielichtdrachen treffen, die Todesschwinge helfen, werden wir sie töten müssen. Sitzt auf, schnell!", sourceObjective = "Steigt auf einen Zinnoberroten Vorposten. Tötet 8 Zwielichtschattendrachen.", completion = "Dank Eures schnellen Handelns lebt die Königin der Drachen noch. Sie wird zurück zum Wyrmruhtempel gebracht, um sich zu erholen.\n\nAber die Schlacht war kein vollständiger Fehlschlag. Todesschwinge ist schwer verwundet. Ich vermute, er wird sich verstecken, um zu Kräften zu kommen. Alexstrasza hat uns Zeit verschafft, um zuzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28759] = { id = 28759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione des Schwarzfels.", completion = "Hervorragende Arbeit, {name}. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28760] = { id = 28760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Orsis", description = "Die große Stadt Orsis wurde von den Armeen der Lüfte angegriffen.\n\nWir wurden gefangengenommen. Und dabei waren wir noch diejenigen, die Glück hatten.\n\nDie meisten starben, begraben unter dem schweren Wüstensand.\n\nAl'Akirs Kalif Asaad hat den Angriff befohlen... und dafür soll er mit dem Leben bezahlen.", sourceObjective = "Tötet Asaad.", completion = "Seid gesegnet. Bitte nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28762] = { id = 28762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28763] = { id = 28763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", sourceObjectiveStatus = "unverified-source-field" }
