quests[28771] = { id = 28771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich von hier lauern Spione der Schwarzfelsorcs. Sie kundschaften uns mit ihren Handfernrohren aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir sehr wohl wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione der Schwarzfelsorcs.", sourceObjectiveStatus = "unverified-source-field" }
