quests[28789] = { id = 28789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürzt Euch in die Schlacht!", description = "Während Ihr unterwegs wart um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, {name}!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", sourceObjective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28790] = { id = 28790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Einladung", description = "<Ein ungewohntes Gefühl steigt in Euch auf und überflutet Euren Geist mit Gedanken und Bildern.>\n\nHöret meine Worte, {name}.\n\nEine fürchterliche Krise hält unsere Welt fest in ihrem Griff. \n\nIch rufe Euch an, uns in dieser verzweifelten Stunde Hilfe zu leisten.\n\nIch bin Krogar.\n\nSucht mich umgehend auf und Euer Schicksal wird sich enthüllen.\n\nIhr findet mich nördlich der Gasse in Orgrimmar.", sourceObjective = "Scharfseher Krogar will, dass Ihr Euch mit ihm in Orgrimmar trefft.", completion = "Möge Euer Sinn für Ehre und Pflicht Azeroth gute Dienste leisten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28791] = { id = 28791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28792] = { id = 28792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", sourceObjectiveStatus = "unverified-source-field" }
quests[28793] = { id = 28793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinischer Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28794] = { id = 28794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", sourceObjectiveStatus = "unverified-source-field" }
