quests[28822] = { id = 28822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28823] = { id = 28823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28824] = { id = 28824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorener Sohn", description = "Eins meiner Kinder ist nicht bei mir, {name}.\n\nEr ist bei den Schattenhammerkultisten im Steinernen Kern im Tempel der Erde zurückgeblieben.\n\nIch habe meine anderen Kinder losgeschickt, um ihn von der finsteren Magie zu befreien, die ihn davon abhält, hierher zurückzukehren... Aber es wirkt keine Magie auf ihn ein.\n\nGeht in den Steinernen Kern und vernichtet Ozruk. Er muss zurück zur Erde aus der er gekommen ist.", sourceObjective = "Vernichtet Ozruk.", progress = "Ist es vollbracht, {race}?", completion = "<Therazanes Augen erscheinen etwas kristalliner, als es Euch in Erinnerung ist.>\n\nOzruk ist nun wieder Teil der Erde, aus der er gekommen ist.\n\nNehmt Eure Belohnung entgegen und geht wieder, {name}. Ich wünsche, alleine gelassen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28825] = { id = 28825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Einladung", description = "<Ein ungewohntes Gefühl steigt in Euch auf und überflutet Euren Geist mit Gedanken und Bildern.>\n\nHöret meine Worte, {name}.\n\nEine fürchterliche Krise hält unsere Welt fest in ihrem Griff. \n\nIch rufe Euch an, uns in dieser verzweifelten Stunde Hilfe zu leisten.\n\nIch bin Naraat.\n\nSucht mich umgehend auf und Eure Berufung wird sich enthüllen.\n\nIch erwarte Euch am Östlichen Erdschrein in Sturmwind.", sourceObjective = "Sprecht mit Naraat dem Erdsprecher in Sturmwind.", completion = "Möge Euer Sinn für Ehre und Pflicht Azeroth gute Dienste leisten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28826] = { id = 28826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Sturms", description = "Seid gegrüßt, Held von Azeroth.\n\nIm Namen des Irdenen Rings danke ich Euch, dass Ihr meinem Ruf gefolgt seid.\n\nEuer Name ist uns nicht unbekannt, {name}.\n\nDie Zahl Eurer Heldentaten und Errungenschaften ist Legion. Azeroth steht schon jetzt tief in Eurer Schuld und dennoch bedarf das Land erneut seiner Helden.\n\nIch bin nur ein Bote. Eine mächtige Präsenz wünscht mit Euch zu sprechen.\n\nSchaut in die Wasser der Weitsicht und sehet, in welcher Zwangslage sich unserer Welt befindet.", sourceObjective = "Naraat der Erdsprecher will, dass Ihr in die Wasser der Weitsicht schaut.", progress = "Ja, {class}?", completion = "Jetzt, da Ihr die Wahrheit gesehen habt, werdet Ihr Euch dazu entschließen zu dienen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28827] = { id = 28827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefe", description = "Der Irdene Ring hat die wasserreichen Gefilde von Vashj'ir als Quelle zerstörerischer Energien des Feindes ausgemacht.\n\nEs ist noch immer unklar, mit welchen Gefahren wir es hier zu tun haben. Jegliche Informationen, die Ihr sammeln könnt, sind von großem Wert.\n\nDie Allianz schickt in diesem Augenblick Kriegsschiffe in die Region. Um dorthin zu gelangen, begebt Euch in den Nordwesten Sturmwinds und sprecht mit Rekrutierer Burns im Hafen von Sturmwind.\n\nMögen die Geister Euch leiten, {name}.", sourceObjective = "Sprecht mit Rekrutierer Burns im Hafen von Sturmwind in Sturmwind.", completion = "Alle unsere Kriegsschiffe sind in See gestochen, um gegen die Horde zu kämpfen. Ihr werdet das Söldnerschiff nehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28828] = { id = 28828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Eier", description = "Ich habe keinen sehr anspruchsvollen Gaumen, aber selbst ich kann den Geschmack dieser Schimären nicht ertragen, die man in dieser Gegend findet. Ihre Eier sind dagegen etwas ganz anderes.\n\nSchimäreneier sind die reichhaltigsten, butterigsten Eier diesseits von Orgrimmar. Viel besser als langweilige Euleneier und nicht so schwefelhaltig wie diese merkwürdigen Wildekineier.\n\nIch nehme Euch so viele davon ab, wie Ihr sammeln könnt. Begebt Euch nach Norden und haltet nach ihren Nestern im Schnee Ausschau.", sourceObjective = "Treibt 40 Zugwindeier auf.", progress = "Mmmm...", completion = "Schön. Eier.\n\nDie passen wunderbar zu einem kleinen Bärenschinken. Hey, Francis, ist noch Bärenfleisch da?", sourceObjectiveStatus = "unverified-source-field" }
quests[28829] = { id = 28829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasiermesserscharfe Schnäbel", description = "Ihr fragt, was mir zugestoßen ist? Hört zu, {class} und zwar gut, denn meine Geschichte beschreibt eine echte Tragödie...\n\nIch wurde hierher ins Eulenflügeldickicht gesandt, um ein paar Relikte ausfindig zu machen. Ich bin nur bis hierhergekommen, bevor ich von einem wilden Ansturm von Flügelschlagen und Krallen überwältigt wurde.\n\nWie sie brüllten und hackten, {class}!\n\nHier lag ich dann, ein gebrochener Orc mit nichts weiter als meiner Rache im Sinn. Bitte, {class}, wenn Ihr auch nur ein wenig Ehrgefühl im Leib habt, werdet Ihr in das Eulenflügeldickicht ziehen und mir helfen, das zurückzuholen, was mir gehört.", sourceObjective = "Tötet 12 Eulenbestien im Eulenflügeldickicht.", completion = "Meine Ehre ist wiederhergestellt.\n\nTeilweise.\n\nMeine Geschichte setzt sich fort, {class}, denn ich habe noch weitere Teile meiner Ehre an anderen Stellen in diesem Wald verloren.\n\nEs war für mich keine sehr leichte Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[28830] = { id = 28830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Apfel fällt nicht weit vom Stamm", description = "Meine rätselhaften Wohltäter haben mir mehr als eine Aufgabe gegeben. Die zweite Aufgabe hat mich weiter nach Süden in die Frosthauchschlucht gebracht. Ich war überrascht, zu erfahren, dass die Schluchtbrücke entzwei ist und dadurch das Reisen über Land von einer Seite auf die andere unmöglich ist.\n\nDarüber hinaus wurden die jüngeren Frosthagelkipper von ihren stärkeren, ausgewachsenen Eltern getrennt. Ich dachte, dass ich sie im Kampf besiegen könnte.\n\nDa habe ich falsch gelegen. Zu meiner Schande war ich dazu gezwungen, die Flucht zu ergreifen.\n\nErteilt diesen Frosthagelkippern eine Lektion, {name}. Schlagt sie im Kampf.", sourceObjective = "Tötet 8 Frosthagelkipper.", completion = "Seid froh, dass die Schlucht die ausgewachsenen Riesen von dieser Seite abschneidet. Sie sind viel zäher als diese Frosthagelkipper, gegen die Ihr kämpft.\n\nIch fühle mich verjüngt durch Euren Mut, {class}. Vielleicht ist doch noch nicht alle Hoffnung verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[28831] = { id = 28831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hol Dich der Teufel, Frostilicus!", description = "Die Frosthagelriesen wären kein Problem gewesen, hätte es nicht diesen verdammten Frostilicus gegeben. Als die Erde bebte und die Brücke entzwei ging, traten er und seine Wasserelemente aus der Erde hervor und übernahmen den Boden der Frosthauchschlucht. So vertrieben sie die Riesen.\n\nHol Dich der Teufel, Frostilicus!\n\nIhr würdet mir eine große Ehre erweisen, wenn Ihr ihn zurück in die Erde treibt, {class}. Ihr findet ihn im Süden auf dem Boden der Schlucht.", sourceObjective = "Vernichtet Frostilicus.", completion = "Wenn ich meine Verletzungen überlebe, werde ich Euren Namen niemals vergessen, {class}.\n\nImmer wenn der Wind durch die Bäume rauscht, werde ich Euren Namen hören.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28832] = { id = 28832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtufer", description = "Also gut, steigt einfach in das Wasserflugzeug hinter mir und ich flieg' Euch ins Hochland.\n\nWir müssen uns bei 'nem Typen melden, den sie \"Leutnant Fawkes\" nennen. Ich hab' dem König versprochen, dass wir rucki-zucki dort sind, also hab' ich mir die Freiheit genommen, ein wenig überflüssiges Gewicht abzuwerfen. Zum Beispiel Sicherheitsgurte. Fallschirme. Karten. Stabilisatoren. Ein Landungsgestell.\n\nIch konnte mit diesen Dingern ohnehin nie richtig \"landen\".", sourceObjective = "Sprecht mit Leutnant Fawkes in Hochstade im Schattenhochland.", completion = "Das Letzte, was ich vom Himmel fallen zu sehen erwartet hätte, seid Ihr beide. Hochstade wird angegriffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28833] = { id = 28833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Erdsprecher!", description = "Gut! Ihr habt Verbündete mitgebracht.\n\nIhr müsst Euch beeilen, wenn wir Erunak retten wollen.\n\nKämpft Euch einen Weg durch Neptulons Hallen frei. Findet den Schamanen und befreit ihn von diesen Würmern... Wenn er noch lebt.\n\nHabt keine Sorge, dass sie Euch in den Rücken fallen. Nichts und niemand kommt an mir vorbei!", sourceObjective = "Rettet Erunak Steinsprecher.", completion = "Was sagt Ihr? Ihr... rettet mich?\n\n<Erunak lächelt Euch an.>\n\nEs wird etwas dauern, bis ich mich daran gewöhne.", sourceObjectiveStatus = "unverified-source-field" }
quests[28834] = { id = 28834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Erdsprecher!", description = "Gut! Ihr habt Verbündete mitgebracht.\n\nIhr müsst Euch beeilen, wenn wir Erunak retten wollen.\n\nGeht jetzt. Kämpft Euch einen Weg durch Neptulons Hallen frei. Findet den Schamanen und befreit ihn von diesen Würmern... Wenn er noch lebt.\n\nSorgt Euch nicht, dass sie Euch in den Rücken fallen könnten. Ich bemühe mich, dass nichts und niemand an mir vorbeikommt!", sourceObjective = "Rettet Erunak Steinsprecher.", completion = "Was sagt Ihr? Ihr... rettet mich?\n\n<Erunak lächelt Euch an.>\n\nEs wird etwas dauern, bis ich mich daran gewöhne.", sourceObjectiveStatus = "unverified-source-field" }
quests[28836] = { id = 28836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden der Meerhexe", description = "Diese widerliche Schlange hat einen tausendfachen Tod verdient!\n\nEs wird nicht leicht sein. Sie und ihre Diener haben sich an diesem Ort fest verschanzt, aber sie ist von ihrem Kampf gegen Neptulon sicherlich erschöpft.\n\nJetzt ist die richtige Zeit, um zuzuschlagen! Eine Möglichkeit wie diese wird sich uns nicht wieder bieten.\n\nDurchbohrt sie, {name}!", sourceObjective = "Besiegt Lady Naz'jar im Thron der Gezeiten.", completion = "Gut gemacht, {name}!\n\nIhr solltet wissen, dass ohne Eure Hilfe die Sache hier ganz anders aussehen würde.\n\nIch wäre nicht nur längst tot, sondern die Naga und ihre Verbündeten würden ungehindert über die Meere herrschen.\n\nDer König selbst soll von Euren Heldentaten in diesen Gefilden erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28837] = { id = 28837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelbare Bestien", description = "Wir, die blauen Drachen wurden gezwungen, unsere Heimat Mazthoril zu verlassen. Ein Betrüger namens Umbranse hat den Augenblick unserer größten Ohnmacht ausgenutzt und hält nun die Höhle besetzt.\n\nMazthoril ist ein Ort extrem wirksamer Magie und er weiß sie nicht zu beherrschen. Sogar die Tiere und Pflanzen der Umgebung leiden darunter.\n\nDie Biester in der Nähe wurden gewandelt. Bitte, {race}, ich muss Euch um einen Gefallen ersuchen. Sammelt ihre Gehirne, sodass ich herausfinden kann, ob ich die wilde Magie von Umbranse rückgängig machen kann.", sourceObjective = "Beschafft 5 manaverwirrte Gehirne von wandelbaren Bestien.", progress = "Mazthoril gehört dem Blauen Drachenschwarm. Es ist nicht richtig, so wie es jetzt ist.", completion = "Lasst mich sehen, was ich damit anstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[28838] = { id = 28838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Standhaftigkeit der Eulenbestien", description = "So ein Ärger. Was immer Umbranse getan hat, es verhindert, dass ich seine Magie rückgängig machen kann.\n\nEr ist weiser, als ich es erwartet hatte.\n\nAber ich habe dennoch einen Plan B. Ich habe Eulenbestien gesehen, die in Mazthoril ein und ausgehen, sogar nachdem Umbranse die Herrschaft übernommen hat. Ihre uralte, druidische Magie muss in der Lage sein, die von Umbranse unschädlich zu machen. Glücklicherweise kenne ich das Verhalten der Eulenbestien sehr genau.\n\nReist nach Süden zu Dun Mandarr. Dort findet Ihr eine Truhe mit einem Traumfänger darin.\n\nDas wird Euer erster Schritt sein.", sourceObjective = "Erlangt einen Eulenbestientraumfänger aus Dun Mandarr.", sourceObjectiveStatus = "unverified-source-field" }
quests[28839] = { id = 28839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prähistorische Magie", description = "Die heiligen Höhlen der Eulenbestien befinden sich im Osten. In einigen dieser Höhlen solltet Ihr Totems finden. Ich will, dass Ihr diese Totems auftreibt und von ihnen so viele Essenzen einsammelt, wie ihr könnt. Der Traumfänger sollte diese Essenzen aufsaugen können, sodass wir sie in Mazthoril verwenden können.", sourceObjective = "Gelangt in den Besitz der Essenz des Klauentotems, der Essenz des Lebenstotems und der Essenz des Mondtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[28840] = { id = 28840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterwasser", description = "Ich will nicht, dass unser erster Zug ein Reinfall wird, {name}. Ein derartiges Versagen würde nur unnötig Aufmerksamkeit auf unsere Bemühungen ziehen und Umbranse die Gelegenheit geben, seine Verteidigung auszubauen. Nein, wir müssen das von Anfang an richtig machen.\n\nÜber die Frosthauchschlucht im Süden haben wir Zugang zu mächtigen Eiselementaren. Das Wasser in der Außenhülle dieser Elementare sollte die Energie Eures Traumfängers verstärken und sicherstellen, dass unsere Bemühungen Früchte tragen.\n\nBeschafft dieses Wasser, {name}. Dann kehrt in unser kleines Lager zurück.", sourceObjective = "Beschafft 7 Winterwasser von Eisavataren in der Frosthauchschlucht.", progress = "Schön, Euch wiederzusehen.", completion = "<Haleh überträgt das Wasser auf Euren Traumfänger.>\n\nIhr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28841] = { id = 28841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Versiegelung der Portale", description = "Mazthorils wilde Magie kann unvorstellbares Chaos anrichten, wenn sie falsch eingesetzt wird. Umbranses übermütiges Wirken in den Höhlen hat eine Reihe von Tesserakten geöffnet – mit anderen Worten Portale. Sie stellen Verbindungen zu anderen Welten her. Bevor ich nach Mazthoril zurückkehren kann, müssen diese Tesserakte geschlossen werden.\n\nDer Traumfänger wird die Portale schließen und so könnt Ihr sicher in Umbranses Unterschlupf eindringen. Vernichtet zunächst alles, was aus den Tesserakten hervorkommt, dann verwendet den Traumfänger, um sie schnell zu schließen, bevor sich noch etwas anderes in diese Welt ergießt.", sourceObjective = "Verwendet den machterfüllten Traumfänger, um 5 arkane Tesserakte in Mazthoril zu schließen.", completion = "Es wird etwas dauern, bis Mazthoril sich erholt... aber schließlich wird es wieder wie früher.\n\nDer blaue Drachenschwarm ist noch lange nicht tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[28842] = { id = 28842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbranses Erlösung", description = "Umbranse lauert im hinteren Teil von Mazthoril. Sein Ende ist nah.\n\nUnglücklicherweise bin ich nicht in der Lage, Euch bei dieser Aufgabe zur Seite zu stehen. Zwar würde ich gerne selbst Hand an diese Schlange legen, aber Mazthorils Magie würde mich in seinem derzeitigen Zustand in Stücke reißen. Nein, Ihr müsst dies für mich zum Abschluss bringen.\n\nWenn getan wurde, was getan werden muss, verwendet diesen Siegelring. Er wird Euch sicher zurück zum Ausgang bringen.", sourceObjective = "Besiegt Umbranse den Geistsprecher.", completion = "Ihr habt unseren Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28843] = { id = 28843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden der Meerhexe", description = "Naz'jar! Sie ist diejenige, die für dieses Chaos verantwortlich ist.\n\nSie ist hier irgendwo, {name}. Sie muss nach dem Kampf mit Neptulon erschöpft sein.\n\nJetzt ist die richtige Zeit, um zuzuschlagen! Eine Möglichkeit wie diese wird sich uns nicht wieder bieten.\n\nIch werde mich um alles Gewürm kümmern, was versucht, ihr aus dieser Richtung zu Hilfe zu eilen.\n\nFindet sie, {name}, und spießt sie auf!", sourceObjective = "Legionär Nazgrim will, dass Ihr Lady Naz'jar vernichtet.", completion = "Höllschrei selbst soll von Euren Taten erfahren, {name}.\n\nOhne Euch, wäre die Lage hier viel schlimmer.\n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[28845] = { id = 28845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vortexgipfel", description = "Eine unserer zivilen Führungspersonen wurde von den Luftelementaren gefangen genommen.\n\nIn diesem Augenblick foltern sie ihn vermutlich.\n\nGeht zum Vortexgipfel. Von dort stammen diese verdorbenen Kreaturen. Sucht dort nach Itesh.\n\nDer Eingang zum Vortexgipfel schwebt vor der südöstlichen Küste von Uldum.", sourceObjective = "Findet Itesh im Vortexgipfel.", completion = "Ihr kommt wirklich hierher, weil Ihr mich sucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[28847] = { id = 28847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verfolgung von Umbranse", description = "Wir haben herausgefunden, wo sich Umbranse hier in Winterquell aufhält. Es ist, wie ich es mir gedacht habe.\n\nUmbranse befindet sich in Mazthoril, der Höhle im Südwesten, die einst dem blauen Drachenschwarm gehört hat. Meine Mutter Haleh wird Euch dort empfangen. Sie befindet sich mit ein paar anderen Überlebenden in einem kleinen Lager vor der Höhle.\n\nHaltet Ausschau nach ihrem Lagerfeuer.", sourceObjective = "Meldet Euch bei Haleh im Beryllaufstieg in Winterquell.", completion = "Ihr seid {name}, nicht wahr?\n\nGut, Ihr werdet von großem Nutzen sein. Ich benötige die Hilfe eines {class}, wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28848] = { id = 28848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur des Geistsprechers", description = "Ich habe Geschichten über Umbranse gehört, obwohl ich ihm niemals persönlich begegnet bin. Man erzählt sich, dass er magische Artefakte sammelt, obwohl ich nicht sagen kann, zu welchem Zweck.\n\nGebt diese Information am besten an einen vertrauenswürdigen Verbündeten weiter. Nymn, der Hochelf befindet sich in der Ewigen Warte, der großen Goblinstadt im Nordosten. Erzählt ihm alles, was Ihr heute erfahren habt.", sourceObjective = "Meldet Euch bei Nymn in der Ewigen Warte in Winterquell.", completion = "Umbranse... Ich verstehe. Ich werde diese Information an mein Volk weiterleiten.\n\nIhr werdet kontaktiert, wenn Ihr wieder gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28849] = { id = 28849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthimmel", description = "Ich habe gerade eine Nachricht aus Orgrimmar erhalten. Der Kriegshäuptling will, dass wir bald ausrücken. Wir wären nicht dazu in der Lage, wenn Ihr uns nicht geholfen hättet!\n\nDer Plan sieht vor, dass die Luftflotte sofort aufbricht und die Marine soll kurz darauf folgen. Höllschrei wird die Luftflotte begleiten und hat ausdrücklich verlangt, dass Ihr mit uns mitkommt.\n\nKeine Zeit zu verlieren! Geht zur Südlichen Endhaltestelle der Raketenbahn hier in Azshara und meldet Euch bei Friz Bodendreh an. Ich werde mit dem Zeppelin kommen, um Euch abzuholen.", sourceObjective = "Meldet Euch bei Friz Bodendreh an der Südlichen Endhaltestelle der Raketenbahn in Azshara an.", completion = "Noch ein {class}, wie? Von Eurer Sorte wollen gerade sehr viele ins Hochland. Hier, unterschreibt den Entschädigungsverzicht...", sourceObjectiveStatus = "unverified-source-field" }
